// Revisions
// ---------------------------------------------------------------------------

export type AddRevisionInput = {
  kind: Exclude<RevisionKind, "revert">;
  manifest: unknown;
  spec?: unknown;
  modBuildId?: string | null;
  engine?: EngineRecord | null;
  status?: RevisionStatus;
  message?: string | null;
  /** Optimistic check: the head this revision builds on (null = the project has no revisions yet). Omit to append to whatever the head is. */
  expectedHeadId?: string | null;
};

type InsertRow = {
  kind: RevisionKind; spec: ModSpec | null; manifest: ManifestEntry[]; modBuildId: string | null; engine: EngineRecord | null;
  status: RevisionStatus; message: string | null; revertOfId: string | null; expectedHeadId?: string | null;
};

const lockProject = async (tx: Prisma.TransactionClient, projectId: string) => {
  const rows = await tx.$queryRaw<{ id: string; namespace: string; game: string; headRevisionId: string | null; lastPassingRevisionId: string | null; revisionCount: number }[]>`
    SELECT "id", "namespace", "game", "headRevisionId", "lastPassingRevisionId", "revisionCount"
    FROM "CyrusProject" WHERE "id" = ${projectId} FOR UPDATE`;
  if (!rows.length) throw new EngineStoreError("not_found", "project not found");
  return rows[0];
};

/** Appends queue on the project row lock; give queued writers room before Prisma's 2 s default gives up. */
const TX = { maxWait: 10_000, timeout: 15_000 };

async function insertRevision(projectId: string, row: InsertRow): Promise<CyrusRevision> {
  return db.$transaction(async (tx) => {
    const p = await lockProject(tx, projectId);
    if (row.expectedHeadId !== undefined && row.expectedHeadId !== p.headRevisionId) {
      throw new EngineStoreError("stale_head", "the project moved on since this change was started; reload and try again");
    }
    if (row.spec && (row.spec.namespace !== p.namespace || row.spec.game !== p.game)) {
      throw new EngineStoreError("spec_mismatch", "the spec's game or namespace is not this project's");
    }
    const rev = await tx.cyrusRevision.create({
      data: {
        projectId, seq: p.revisionCount + 1, parentId: p.headRevisionId, kind: row.kind,
        spec: row.spec ? (row.spec as unknown as Prisma.InputJsonValue) : Prisma.DbNull,
        manifest: row.manifest as unknown as Prisma.InputJsonValue,
        modBuildId: row.modBuildId, engine: row.engine ? (row.engine as Prisma.InputJsonValue) : Prisma.DbNull,
        status: row.status, message: row.message, revertOfId: row.revertOfId,
      },
    });
    await tx.cyrusProject.update({
      where: { id: projectId },
      data: { headRevisionId: rev.id, revisionCount: rev.seq, ...(rev.status === "passed" ? { lastPassingRevisionId: rev.id } : {}) },
    });
    return rev;
  }, TX);
}

/** Append a revision on top of the project's head. Validates spec, manifest and engine record first. */
export async function addRevision(projectId: string, input: AddRevisionInput): Promise<CyrusRevision> {
  if (!(REVISION_KINDS as readonly string[]).includes(input.kind) || input.kind === ("revert" as string)) throw new EngineStoreError("bad_kind", `kind must be generated, edited, imported or asset (use revertTo for a revert)`);
  const status = input.status ?? "pending";
  if (!["pending", "passed", "failed"].includes(status)) throw new EngineStoreError("bad_status", "status must be pending, passed or failed");
  const m = validateManifest(input.manifest);
  if (!m.ok) throw new EngineStoreError("bad_manifest", "the file manifest is invalid", m.errors);
  const eng = validateEngineRecord(input.engine);
  if (!eng.ok) throw new EngineStoreError("bad_engine_record", "the engine record is invalid", eng.errors);
  let spec: ModSpec | null = null;
  if (input.spec !== undefined && input.spec !== null) {
    const v = validateModSpec(input.spec, { adapterFor: getAdapter });
    if (!v.ok) throw new EngineStoreError("bad_spec", "the mod spec is invalid", v.errors);
    spec = v.spec;
  }
  return insertRevision(projectId, {
    kind: input.kind, spec, manifest: m.entries, modBuildId: input.modBuildId ?? null, engine: input.engine ? eng.record : null,
    status, message: input.message ?? null, revertOfId: null, expectedHeadId: input.expectedHeadId,
  });
}

/** The one allowed change to a revision: pending -> passed | failed. A pass becomes the project's last passing revision if it is newer. */
export async function setRevisionStatus(revisionId: string, status: "passed" | "failed"): Promise<CyrusRevision> {
  if (status !== "passed" && status !== "failed") throw new EngineStoreError("bad_status", "status must be passed or failed");
  const rev = await db.cyrusRevision.findUnique({ where: { id: revisionId } });
  if (!rev) throw new EngineStoreError("not_found", "revision not found");
  return db.$transaction(async (tx) => {
    const p = await lockProject(tx, rev.projectId);
    const n = await tx.cyrusRevision.updateMany({ where: { id: revisionId, status: "pending" }, data: { status } });
    if (n.count !== 1) throw new EngineStoreError("not_pending", "only a pending revision can change status");
    if (status === "passed") {
      const current = p.lastPassingRevisionId ? await tx.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId }, select: { seq: true } }) : null;
      if (!current || current.seq < rev.seq) await tx.cyrusProject.update({ where: { id: rev.projectId }, data: { lastPassingRevisionId: rev.id } });
    }
    return { ...rev, status };
  }, TX);
}

export async function getHead(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { headRevisionId: true } });
  return p?.headRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.headRevisionId } }) : null;
}

export async function lastPassing(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { lastPassingRevisionId: true } });
  return p?.lastPassingRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId } }) : null;
}

export const getRevision = (id: string) => db.cyrusRevision.findUnique({ where: { id } });
export const listRevisions = (projectId: string) => db.cyrusRevision.findMany({ where: { projectId }, orderBy: { seq: "asc" } });

export const manifestOf = (rev: Pick<CyrusRevision, "manifest">): ManifestEntry[] => (Array.isArray(rev.manifest) ? (rev.manifest as unknown as ManifestEntry[]) : []);

/** Files added / removed / changed going from revision `fromId` to `toId` (same project). */
export async function diffRevisions(fromId: string, toId: string): Promise<ManifestDiff> {
  const [a, b] = await Promise.all([getRevision(fromId), getRevision(toId)]);
  if (!a || !b) throw new EngineStoreError("not_found", "revision not found");
  if (a.projectId !== b.projectId) throw new EngineStoreError("bad_input", "revisions belong to different projects");
  return diffManifests(manifestOf(a), manifestOf(b));
}

/**
 * Revert = a NEW revision on top of the head that restores `targetId`'s spec, files and build link. History is kept.
 * The status carries over: the files are byte-identical (same manifest hashes), so the same checks apply.
 */
export async function revertTo(projectId: string, targetId: string, opts: { message?: string; expectedHeadId?: string | null } = {}): Promise<CyrusRevision> {
  const t = await getRevision(targetId);
  if (!t || t.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const engine = { ...((t.engine as EngineRecord | null) ?? {}), revertOf: t.id };
  return insertRevision(projectId, {
    kind: "revert", spec: (t.spec as unknown as ModSpec | null) ?? null, manifest: manifestOf(t), modBuildId: t.modBuildId, engine,
    status: t.status as RevisionStatus, message: opts.message ?? `Revert to revision ${t.seq}`, revertOfId: t.id, expectedHeadId: opts.expectedHeadId,
  });
}

