export type ToolResult = { ok: boolean; content: string; chars: number };
const out = (ok: boolean, body: unknown): ToolResult => { const content = JSON.stringify(body); return { ok, content, chars: content.length }; };

/** Kinds this plan may use + the tiers it may pick from (both empty = nothing). */
export function access(plan: unknown, proprietaryCleared: boolean): { kinds: CatalogKind[]; tiers: LicenceTier[]; plan: AssetPlan | null } {
  const p = normalizePlan(plan);
  if (!p) return { kinds: [], tiers: [], plan: null };
  const kinds = CATALOG_KINDS.filter((k) => canAsset(p, gateKindOf(k), "create").ok);
  const tiers = PLAN_TIERS[p].filter((t) => t !== "proprietary-nxeon" || proprietaryCleared);
  return { kinds, tiers: [...tiers], plan: p };
}

const keyFact = (e: CatalogEntry): Record<string, number> => {
  const t = e.tech;
  if (e.kind === "model" && t.triangles != null) return { tris: t.triangles };
  if ((e.kind === "sound" || e.kind === "music") && t.durationS != null) return { sec: Math.round(t.durationS * 10) / 10 };
  if (t.width) return { px: t.width };
  return {};
};

/** One compact search row (~45-70 tokens). */
export async function compactRow(e: CatalogEntry, game: string | null, index: CatalogIndex, groupSize = 1): Promise<Record<string, unknown>> {
  const fit = game ? e.games[game]?.fit ?? "unknown" : undefined;
  return {
    id: `c:${await index.shortId(e.id)}`, t: e.title, d: e.shortDescription, k: e.kind,
    tags: e.tags.filter((x) => x !== e.style).slice(0, 5), ...(fit ? { fit } : {}), q: e.quality.score, ...keyFact(e),
    ...(groupSize > 1 ? { variants: groupSize } : {}),
  };
}

export async function catalogSearch(input: { query?: unknown; kind?: unknown; game?: unknown; minQuality?: unknown; limit?: unknown }, ctx: ToolContext): Promise<ToolResult> {
  const query = typeof input.query === "string" ? input.query.trim().slice(0, 120) : "";
  if (query.length < 2) return out(false, { error: "query must be 2-120 characters" });
  const a = access(ctx.plan, ctx.proprietaryCleared);
  if (!a.plan) return out(false, { error: "plan_unknown: assets cannot be picked right now" });
  let kinds = a.kinds;
  if (input.kind != null) {
    if (!(CATALOG_KINDS as readonly unknown[]).includes(input.kind)) return out(false, { error: `unknown kind; use one of ${CATALOG_KINDS.join(", ")}` });
    const k = input.kind as CatalogKind;
    if (!kinds.includes(k)) { const d = canAsset(a.plan, gateKindOf(k), "create"); return out(false, { error: "asset_locked", needs: d.ok ? null : d.needs ?? null }); }
    kinds = [k];
  }
  if (!kinds.length || !a.tiers.length) return out(false, { error: "asset_locked: this plan cannot use library assets" });
  const game = typeof input.game === "string" && /^[a-z][a-z0-9-]{1,31}$/.test(input.game) ? input.game : ctx.game;
  const minQuality = Number.isInteger(input.minQuality) ? Math.max(0, Math.min(100, input.minQuality as number)) : 40;
  const limit = Number.isInteger(input.limit) ? Math.max(1, Math.min(SEARCH_LIMIT_MAX, input.limit as number)) : 6;
  const r = await ctx.index.search({ text: query, kinds, game, minQuality, tiers: a.tiers, limit: limit * 2, statuses: ["published"] });
  // one row per (kind, title): identical-looking assets (same name in two packs, HDRI resolutions) count as variants
  const rows: Record<string, unknown>[] = [];
  const seenTitle = new Map<string, Record<string, unknown>>();
  for (const h of r.hits) {
    const k = `${h.entry.kind}|${h.entry.title.toLowerCase()}`;
    const prev = seenTitle.get(k);
    if (prev) { prev.variants = (Number(prev.variants) || 1) + h.groupSize; continue; }
    const row = await compactRow(h.entry, game, ctx.index, h.groupSize);
    seenTitle.set(k, row); rows.push(row);
  }
  // hard budget: drop descriptions, then rows, until the result fits
  let body: Record<string, unknown> = { n: r.total, game, rows: rows.slice(0, limit) };
  if (JSON.stringify(body).length > RESULT_CHAR_BUDGET) body = { ...body, rows: rows.slice(0, limit).map(({ d: _d, ...x }) => x) };
  while (JSON.stringify(body).length > RESULT_CHAR_BUDGET && (body.rows as unknown[]).length > 1) body = { ...body, rows: (body.rows as unknown[]).slice(0, -1) };
  if (!rows.length) body.hint = "no match: try other words for the situation, another kind, or a lower minQuality";
  return out(true, body);
}

export async function catalogGet(input: { id?: unknown }, ctx: ToolContext): Promise<ToolResult> {
  const id = typeof input.id === "string" ? input.id : "";
  const e = await ctx.index.get(id);
  const a = access(ctx.plan, ctx.proprietaryCleared);
  // an entry the caller may not use is reported as not found (no metadata leak across gates)
  if (!e || e.status !== "published" || !a.kinds.includes(e.kind) || !a.tiers.includes(e.licence.tier)) return out(false, { error: "not_found" });
  const t = e.tech;
  const tech = Object.fromEntries(Object.entries({
    format: t.format, tris: t.triangles, bounds_m: t.bounds, rigged: t.rigged, anims: t.animations, materials: t.materials,
    px: t.width && t.height ? `${t.width}x${t.height}` : null, maps: t.maps, tileable: t.tileable, sec: t.durationS, hz: t.sampleRate, ch: t.channels, lufs: t.lufs, loop: t.loopable,
  }).filter(([, v]) => v != null && !(Array.isArray(v) && !v.length)));
  const fit = ctx.game ? e.games[ctx.game] ?? null : null;
  return out(true, {
    ref: catalogRef(e.id), t: e.title, d: e.shortDescription, k: e.kind, cat: e.categories.primary, style: e.style,
    tags: e.tags.slice(0, 10), useFor: e.useFor.map(useForLabel).slice(0, 4), q: e.quality.score,
    fails: e.quality.checks.filter((c) => c.status === "fail").map((c) => c.id),
    ...(fit ? { fit: { game: ctx.game, fit: fit.fit, why: fit.reason, notes: fit.notes, transform: fit.transform } } : { fit: { game: ctx.game, fit: "unknown" } }),
    tech, licence: { tier: e.licence.tier, spdx: e.licence.spdx, attribution: e.licence.attribution },
    ...(e.licence.tier === "proprietary-nxeon" ? { rule: "proprietary library: ship transformed (pitch/edit), never the original file" } : {}),
  });
}

export async function handleCatalogTool(name: string, input: unknown, ctx: ToolContext): Promise<ToolResult> {
  const i = (input && typeof input === "object" ? input : {}) as Record<string, unknown>;
  if (name === "catalog_search") return catalogSearch(i, ctx);
  if (name === "catalog_get") return catalogGet(i, ctx);
  return out(false, { error: `unknown tool ${name}` });
}

export type SlotDecision = { ok: true; entry: CatalogEntry; transform: string[] } | { ok: false; code: "not_library" | "bad_ref" | "not_found" | "not_published" | "kind_mismatch" | "asset_locked" | "tier_locked" | "no_fit"; reason: string };

/** What the build service runs for a ModSpec asset slot with source "library" (after gateSpecAssets). */
export async function resolveLibrarySlot(slot: Pick<AssetSlot, "id" | "kind" | "source"> & { libraryRef?: string }, ctx: ToolContext): Promise<SlotDecision> {
  if (slot.source !== "library") return { ok: false, code: "not_library", reason: `slot ${slot.id} is not a library slot` };
  if (!slot.libraryRef || !CATALOG_REF_RE.test(slot.libraryRef)) return { ok: false, code: "bad_ref", reason: `slot ${slot.id} needs libraryRef cat:<sha256>` };
  const e = await ctx.index.get(slot.libraryRef.slice(4));
  if (!e) return { ok: false, code: "not_found", reason: `${slot.libraryRef} is not in the catalog` };
  if (e.status !== "published") return { ok: false, code: "not_published", reason: `${slot.libraryRef} is ${e.status}` };
  const want = gateKindOf(e.kind);
  if (!(want === slot.kind || (slot.kind === "ui" && want === "texture"))) return { ok: false, code: "kind_mismatch", reason: `slot ${slot.id} is ${slot.kind}, the asset is a ${e.kind}` };
  const d = canAsset(ctx.plan, slot.kind, "create");
  if (!d.ok) return { ok: false, code: "asset_locked", reason: d.reason };
  const a = access(ctx.plan, ctx.proprietaryCleared);
  if (!a.tiers.includes(e.licence.tier)) return { ok: false, code: "tier_locked", reason: `${e.licence.tier} assets are not available on this plan${e.licence.tier === "proprietary-nxeon" && !ctx.proprietaryCleared ? " (library not cleared)" : ""}` };
  const fit = ctx.game ? e.games[ctx.game] : undefined;
  if (fit?.fit === "no") return { ok: false, code: "no_fit", reason: fit.reason };
  return { ok: true, entry: e, transform: fit?.transform ?? [] };
}

