// Cyrus API v1: the wire shapes (Zod), the single source of the OpenAPI contract (docs/api/cyrus-v1.openapi.yaml is
// GENERATED from these by tools/cyrus-api/gen-openapi.ts; test/cyrus-api-contract.test.ts fails on drift).
// Domain documents are REUSED, never copied: ModSpec (engine-core/spec.ts), CatalogEntry (library/v2/entry.ts),
// MotionSpec (motion/spec.ts). Envelopes are loose objects: v1 grows by adding fields, so clients must ignore
// unknown ones. Pure, client-safe. HOST SEAM: no Nxeon imports.
import { z } from "zod";
import { ModSpecV1Schema, REVISION_KIND_LIST } from "./domain";
import { CATALOG_KINDS, CatalogEntryV1Z, LicenceZ, FITS } from "../../library/v2/entry";
import { MotionSpecSchema } from "../../motion/spec";

export const API_VERSION = "1.0.0";

// ------------------------------------------------------------------------------------------------ errors
/** The engine's structured issue ({path, code, message}, engine-core SpecIssue), reused for every validation error. */
export const IssueZ = z.object({ path: z.string(), code: z.string(), message: z.string() });
export const ERROR_CODES = [
  "bad_request", "unauthorized", "forbidden_scope", "subject_required", "bad_subject", "not_found", "rate_limited",
  "plan_unknown", "asset_locked", "catalog_unavailable", "api_misconfigured", "internal", "idempotency_mismatch",
] as const;
export const ErrorZ = z.looseObject({
  error: z.looseObject({
    /** stable snake_case; new codes may be added within v1 */
    code: z.string(),
    message: z.string(),
    issues: z.array(IssueZ).optional(),
    requestId: z.string(),
  }),
});
export type ApiIssue = z.infer<typeof IssueZ>;

// ------------------------------------------------------------------------------------------------ health
export const HealthZ = z.looseObject({
  ok: z.literal(true),
  api: z.literal("cyrus"),
  version: z.string(),
  time: z.string(),
  /** the calling client and the scopes its token carries */
  client: z.string(),
  scopes: z.array(z.string()),
});

// ------------------------------------------------------------------------------------------------ projects
const iso = z.string().describe("ISO 8601 timestamp");
export const RevisionSummaryZ = z.looseObject({
  id: z.string(),
  seq: z.number().int().min(1),
  kind: z.enum(REVISION_KIND_LIST),
  status: z.enum(["pending", "passed", "failed"]),
  message: z.string().nullable(),
  modBuildId: z.string().nullable(),
  /** number of files in the revision's manifest */
  files: z.number().int().min(0),
  createdAt: iso,
});
export const ProjectZ = z.looseObject({
  id: z.string(),
  game: z.string(),
  /** the project's reserved identifier namespace (nx_<8>) */
  namespace: z.string(),
  title: z.string().nullable(),
  rootBuildId: z.string().nullable(),
  headRevisionId: z.string().nullable(),
  lastPassingRevisionId: z.string().nullable(),
  revisionCount: z.number().int().min(0),
  createdAt: iso,
  updatedAt: iso,
});
export const ProjectDetailZ = ProjectZ.extend({
  head: RevisionSummaryZ.nullable(),
  lastPassing: RevisionSummaryZ.nullable(),
  /** the head revision's ModSpec, when it has one */
  spec: ModSpecV1Schema.nullable(),
});
export const ProjectListZ = z.looseObject({ data: z.array(ProjectZ), nextCursor: z.string().nullable() });

// ------------------------------------------------------------------------------------------------ builds
export const BUILD_STATUSES = ["queued", "planning", "coding", "compiling", "repairing", "scanning", "succeeded", "failed"] as const;
export const BuildZ = z.looseObject({
  id: z.string(),
  /** open enum: a new in-progress state may be added within v1; `terminal` is the stable signal */
  status: z.string().describe(`one of ${BUILD_STATUSES.join(", ")}`),
  terminal: z.boolean(),
  target: z.looseObject({ game: z.string(), version: z.string() }),
  pluginName: z.string().nullable(),
  version: z.string().nullable(),
  prompt: z.string(),
  changeRequest: z.string().nullable(),
  baseBuildId: z.string().nullable(),
  rootBuildId: z.string().nullable(),
  summary: z.string().nullable(),
  error: z.looseObject({ code: z.string().nullable(), message: z.string() }).nullable(),
  artifact: z.looseObject({ name: z.string().nullable(), size: z.number().int().nullable(), sha256: z.string().nullable() }).nullable(),
  attempts: z.number().int(),
  durationMs: z.number().int().nullable(),
  createdAt: iso,
  updatedAt: iso,
  finishedAt: iso.nullable(),
});

// ------------------------------------------------------------------------------------------------ catalog
export const CatalogHitZ = z.looseObject({
  /** full sha256 id; `ref` (cat:<id>) goes into a ModSpec asset slot as { source: "library", libraryRef: ref } */
  id: z.string(),
  ref: z.string(),
  kind: z.enum(CATALOG_KINDS),
  title: z.string(),
  shortDescription: z.string(),
  tags: z.array(z.string()),
  quality: z.number().int(),
  fit: z.enum([...FITS, "unknown"]),
  variants: z.number().int().min(1),
});
export const CatalogSearchZ = z.looseObject({
  data: z.array(CatalogHitZ),
  total: z.number().int().min(0),
  game: z.string().nullable(),
  nextCursor: z.string().nullable(),
});
/** What a caller may see of a CatalogEntry: no provenance paths, no moderation internals. */
export const CatalogEntryPublicZ = CatalogEntryV1Z.pick({
  id: true, kind: true, title: true, shortDescription: true, tags: true, categories: true, useFor: true, style: true,
  quality: true, games: true, tech: true, legalClass: true, thumbnail: true,
}).extend({
  ref: z.string(),
  licence: LicenceZ.pick({ tier: true, spdx: true, attribution: true }),
  /** set for proprietary-nxeon assets: they ship transformed, never as the original file */
  rule: z.string().optional(),
});

// ------------------------------------------------------------------------------------------------ webhooks (Cyrus -> caller)
export const WEBHOOK_EVENTS = ["build.finished", "mod.published", "install.result", "delivery.rolledback", "library.contributed"] as const;
export type WebhookEvent = (typeof WEBHOOK_EVENTS)[number];
const envelope = <T extends string, D extends z.ZodType>(type: T, data: D) => z.looseObject({
  id: z.string(), type: z.literal(type), createdAt: iso,
  /** the stable subject id the event is about (never an email) */
  subject: z.string().nullable(),
  data,
});
export const WebhookBuildFinishedZ = envelope("build.finished", z.looseObject({ buildId: z.string(), projectId: z.string().nullable(), status: z.enum(["succeeded", "failed"]), jarSha256: z.string().nullable(), errorCode: z.string().nullable() }));
export const WebhookModPublishedZ = envelope("mod.published", z.looseObject({ slug: z.string(), buildId: z.string(), version: z.string().nullable() }));
export const WebhookInstallResultZ = envelope("install.result", z.looseObject({ installId: z.string(), serverId: z.string(), ok: z.boolean(), restartRequired: z.boolean(), error: z.string().nullable() }));
export const WebhookDeliveryRolledBackZ = envelope("delivery.rolledback", z.looseObject({ deliveryId: z.string(), serverId: z.string(), failedStep: z.string(), reason: z.string() }));
export const WebhookLibraryContributedZ = envelope("library.contributed", z.looseObject({ ref: z.string(), kind: z.enum(CATALOG_KINDS), status: z.enum(["pending-checks", "published", "held"]) }));

// ------------------------------------------------------------------------------------------------ planned request bodies
export const CreateBuildZ = z.looseObject({
  prompt: z.string().min(3).max(4000),
  target: z.looseObject({ game: z.string(), version: z.string() }),
  baseBuildId: z.string().optional(),
  changeRequest: z.string().max(4000).optional(),
  model: z.string().optional(),
});
export const CreateInstallZ = z.looseObject({
  buildId: z.string(),
  serverId: z.string(),
  mode: z.enum(["install", "update"]).default("install"),
});
export const InstallZ = z.looseObject({
  id: z.string(), buildId: z.string(), serverId: z.string(),
  status: z.enum(["queued", "running", "succeeded", "failed", "rolledback"]),
  error: z.string().nullable(), createdAt: iso, finishedAt: iso.nullable(),
});
export const AccountPlanZ = z.looseObject({ tier: z.string(), balance: z.number().int(), renewsAt: iso.nullable() });

/**
 * Every named component, in the order the OpenAPI file lists them. `out` = response shape (io "output"),
 * `in` = request body (io "input": defaults optional).
 */
export const COMPONENTS: readonly { name: string; schema: z.ZodType; io: "output" | "input" }[] = [
  { name: "Issue", schema: IssueZ, io: "output" },
  { name: "Error", schema: ErrorZ, io: "output" },
  { name: "Health", schema: HealthZ, io: "output" },
  { name: "RevisionSummary", schema: RevisionSummaryZ, io: "output" },
  { name: "Project", schema: ProjectZ, io: "output" },
  { name: "ProjectDetail", schema: ProjectDetailZ, io: "output" },
  { name: "ProjectList", schema: ProjectListZ, io: "output" },
  { name: "Build", schema: BuildZ, io: "output" },
  { name: "CatalogHit", schema: CatalogHitZ, io: "output" },
  { name: "CatalogSearch", schema: CatalogSearchZ, io: "output" },
  { name: "CatalogEntry", schema: CatalogEntryPublicZ, io: "output" },
  { name: "Install", schema: InstallZ, io: "output" },
  { name: "AccountPlan", schema: AccountPlanZ, io: "output" },
  { name: "WebhookBuildFinished", schema: WebhookBuildFinishedZ, io: "output" },
  { name: "WebhookModPublished", schema: WebhookModPublishedZ, io: "output" },
  { name: "WebhookInstallResult", schema: WebhookInstallResultZ, io: "output" },
  { name: "WebhookDeliveryRolledBack", schema: WebhookDeliveryRolledBackZ, io: "output" },
  { name: "WebhookLibraryContributed", schema: WebhookLibraryContributedZ, io: "output" },
