// Cyrus API v1: the operation table + the OpenAPI 3.1 document built from it and from the Zod components
// (./schemas.ts). `x-cyrus-status` is "live" (a handler under app/api/cyrus/v1 answers it, behind CYRUS_API_V1) or
// "planned" (documented, no handler yet); test/cyrus-api-contract.test.ts holds both directions. Pure.
import { z } from "zod";
import { API_VERSION, COMPONENTS, WEBHOOK_EVENTS } from "./schemas";
import { SCOPES, type Scope } from "./scopes";

export type OpStatus = "live" | "planned";
export type Param = { name: string; in: "query" | "path" | "header"; required?: boolean; description: string; schema: Record<string, unknown> };
export type Operation = {
  id: string;
  method: "get" | "post" | "put" | "delete";
  /** relative to /api/cyrus/v1 */
  path: string;
  summary: string;
  tag: string;
  status: OpStatus;
  scopes: Scope[];
  /** needs the Cyrus-Subject assertion (data of one user) */
  subject: boolean;
  params?: Param[];
  /** POST/PUT: Idempotency-Key header required */
  idempotent?: boolean;
  body?: { ref?: string; schema?: Record<string, unknown> };
  ok: { status: number; ref?: string; description: string; contentType?: string };
};

const ref = (name: string) => ({ $ref: `#/components/schemas/${name}` });
const limit: Param = { name: "limit", in: "query", description: "page size (1-100, default 20)", schema: { type: "integer", minimum: 1, maximum: 100 } };
const cursor: Param = { name: "cursor", in: "query", description: "opaque cursor from nextCursor", schema: { type: "string", maxLength: 200 } };
const pathId = (name: string, pattern?: string): Param => ({ name, in: "path", required: true, description: `${name}`, schema: { type: "string", ...(pattern ? { pattern } : { maxLength: 64 }) } });

export const PROJECT_ID_PATTERN = "^cp[0-9a-f]{20}$";
export const BUILD_ID_PATTERN = "^[A-Za-z0-9_-]{1,64}$";
export const ENTRY_ID_PATTERN = "^(cat:)?[0-9a-f]{12,64}$";

export const OPERATIONS: readonly Operation[] = [
  { id: "getHealth", method: "get", path: "/health", tag: "meta", status: "live", scopes: [], subject: false,
    summary: "Liveness + who is calling (client, scopes).", ok: { status: 200, ref: "Health", description: "API is up" } },
  { id: "listProjects", method: "get", path: "/projects", tag: "projects", status: "live", scopes: ["projects:read"], subject: true,
    summary: "The subject's projects, newest first.", params: [limit, cursor], ok: { status: 200, ref: "ProjectList", description: "one page" } },
  { id: "getProject", method: "get", path: "/projects/{projectId}", tag: "projects", status: "live", scopes: ["projects:read"], subject: true,
    summary: "One project with its head + last passing revision and the head ModSpec.", params: [pathId("projectId", PROJECT_ID_PATTERN)],
    ok: { status: 200, ref: "ProjectDetail", description: "the project" } },
  { id: "createProject", method: "post", path: "/projects", tag: "projects", status: "planned", scopes: ["projects:write"], subject: true, idempotent: true,
    summary: "Create a project (reserves its namespace).", body: { schema: { type: "object", required: ["game"], properties: { game: { type: "string" }, title: { type: "string", maxLength: 120 } } } },
    ok: { status: 201, ref: "Project", description: "created" } },
  { id: "listRevisions", method: "get", path: "/projects/{projectId}/revisions", tag: "projects", status: "planned", scopes: ["projects:read"], subject: true,
    summary: "Revision history (append-only).", params: [pathId("projectId", PROJECT_ID_PATTERN), limit, cursor], ok: { status: 200, description: "one page" } },
  { id: "createRevision", method: "post", path: "/projects/{projectId}/revisions", tag: "projects", status: "planned", scopes: ["projects:write"], subject: true, idempotent: true,
    summary: "Append a revision on the head (expectedHeadId = optimistic concurrency, 409 stale_head).", params: [pathId("projectId", PROJECT_ID_PATTERN)],
    body: { schema: { type: "object", required: ["spec"], properties: { spec: ref("ModSpecInput"), expectedHeadId: { type: ["string", "null"] }, message: { type: "string", maxLength: 300 } } } },
    ok: { status: 201, ref: "RevisionSummary", description: "appended" } },
  { id: "revertProject", method: "post", path: "/projects/{projectId}/revert", tag: "projects", status: "planned", scopes: ["projects:write"], subject: true, idempotent: true,
    summary: "Revert = a NEW revision restoring an older one.", params: [pathId("projectId", PROJECT_ID_PATTERN)],
    body: { schema: { type: "object", required: ["revisionId"], properties: { revisionId: { type: "string" }, expectedHeadId: { type: ["string", "null"] } } } },
    ok: { status: 201, ref: "RevisionSummary", description: "appended" } },
  { id: "putMotionDraft", method: "put", path: "/projects/{projectId}/drafts/motion/{key}", tag: "projects", status: "planned", scopes: ["projects:write"], subject: true, idempotent: true,
    summary: "Save a MotionSpec draft for a project slot.", params: [pathId("projectId", PROJECT_ID_PATTERN), pathId("key", "^[a-z][a-z0-9_]{1,31}$")],
    body: { ref: "MotionSpecInput" }, ok: { status: 200, description: "saved" } },
  { id: "listBuilds", method: "get", path: "/builds", tag: "builds", status: "planned", scopes: ["builds:read"], subject: true,
    summary: "The subject's builds, newest first.", params: [limit, cursor], ok: { status: 200, description: "one page" } },
  { id: "createBuild", method: "post", path: "/builds", tag: "builds", status: "planned", scopes: ["builds:write"], subject: true, idempotent: true,
    summary: "Start an AI build (plan + token gate server side).", body: { ref: "CreateBuild" }, ok: { status: 202, ref: "Build", description: "queued" } },
  { id: "getBuild", method: "get", path: "/builds/{buildId}", tag: "builds", status: "live", scopes: ["builds:read"], subject: true,
    summary: "One build's status, target, artifact facts and error.", params: [pathId("buildId", BUILD_ID_PATTERN)], ok: { status: 200, ref: "Build", description: "the build" } },
  { id: "cancelBuild", method: "post", path: "/builds/{buildId}/cancel", tag: "builds", status: "planned", scopes: ["builds:write"], subject: true, idempotent: true,
    summary: "Cancel a running build (its token hold is released).", params: [pathId("buildId", BUILD_ID_PATTERN)], ok: { status: 200, ref: "Build", description: "cancelled" } },
  { id: "getBuildArtifact", method: "get", path: "/builds/{buildId}/artifact", tag: "builds", status: "planned", scopes: ["builds:read"], subject: true,
    summary: "302 to a short-lived signed download URL of the jar.", params: [pathId("buildId", BUILD_ID_PATTERN)], ok: { status: 302, description: "redirect to the artifact" } },
  { id: "streamBuildEvents", method: "get", path: "/builds/{buildId}/events", tag: "builds", status: "planned", scopes: ["builds:read"], subject: true,
    summary: "Build progress as server-sent events.", params: [pathId("buildId", BUILD_ID_PATTERN)], ok: { status: 200, description: "event stream", contentType: "text/event-stream" } },
  { id: "createInstall", method: "post", path: "/installs", tag: "installs", status: "planned", scopes: ["installs:write"], subject: true, idempotent: true,
    summary: "Put a build on one of the subject's servers (runs through the host; result by webhook install.result).", body: { ref: "CreateInstall" },
    ok: { status: 202, ref: "Install", description: "accepted" } },
  { id: "getInstall", method: "get", path: "/installs/{installId}", tag: "installs", status: "planned", scopes: ["installs:read"], subject: true,
    summary: "One install request and its result.", params: [pathId("installId")], ok: { status: 200, ref: "Install", description: "the install" } },
  { id: "searchCatalog", method: "get", path: "/catalog/search", tag: "catalog", status: "live", scopes: ["catalog:read"], subject: true,
    summary: "Search the asset catalog; only assets the subject's plan may use are returned (same gates as catalog_search).",
    params: [
      { name: "q", in: "query", required: true, description: "what the asset is for, in plain words", schema: { type: "string", minLength: 2, maxLength: 120 } },
      { name: "kind", in: "query", description: "asset kind", schema: { type: "string" } },
      { name: "game", in: "query", description: "game id for fit ranking", schema: { type: "string", pattern: "^[a-z][a-z0-9-]{1,31}$" } },
      { name: "minQuality", in: "query", description: "minimum quality score (default 40)", schema: { type: "integer", minimum: 0, maximum: 100 } },
      { name: "limit", in: "query", description: "page size (1-20, default 10)", schema: { type: "integer", minimum: 1, maximum: 20 } },
      cursor,
    ],
    ok: { status: 200, ref: "CatalogSearch", description: "one page of hits" } },
  { id: "getCatalogEntry", method: "get", path: "/catalog/entries/{entryId}", tag: "catalog", status: "live", scopes: ["catalog:read"], subject: true,
    summary: "One catalog entry (public fields). An entry the plan may not use answers 404.", params: [pathId("entryId", ENTRY_ID_PATTERN)],
    ok: { status: 200, ref: "CatalogEntry", description: "the entry" } },
  { id: "listMods", method: "get", path: "/mods", tag: "mods", status: "planned", scopes: ["mods:read"], subject: false,
    summary: "Published mod listings.", params: [limit, cursor], ok: { status: 200, description: "one page" } },
  { id: "getMod", method: "get", path: "/mods/{slug}", tag: "mods", status: "planned", scopes: ["mods:read"], subject: false,
    summary: "One published mod listing.", params: [pathId("slug", "^[a-z0-9-]{2,80}$")], ok: { status: 200, description: "the listing" } },
  { id: "getAccountPlan", method: "get", path: "/account/plan", tag: "account", status: "planned", scopes: ["account:read"], subject: true,
    summary: "The subject's plan tier and token balance.", ok: { status: 200, ref: "AccountPlan", description: "plan" } },
];

const WEBHOOK_COMPONENT: Record<(typeof WEBHOOK_EVENTS)[number], string> = {
  "build.finished": "WebhookBuildFinished", "mod.published": "WebhookModPublished", "install.result": "WebhookInstallResult",
  "delivery.rolledback": "WebhookDeliveryRolledBack", "library.contributed": "WebhookLibraryContributed",
};

/** app/api/cyrus/v1 route file that answers an operation path. */
export const handlerFileFor = (path: string) => `app/api/cyrus/v1${path.replace(/\{([A-Za-z]+)\}/g, "[$1]")}/route.ts`;

const errorResponse = (description: string) => ({ description, content: { "application/json": { schema: ref("Error") } } });

/** Zod components -> JSON Schema (draft 2020-12, which OpenAPI 3.1 uses), cross-referenced by name. */
export function componentSchemas(): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const io of ["output", "input"] as const) {
    const reg = z.registry<{ id: string }>();
    for (const c of COMPONENTS.filter((x) => x.io === io)) reg.add(c.schema, { id: c.name });
    const r = z.toJSONSchema(reg, { io, uri: (id) => `#/components/schemas/${id}`, unrepresentable: "any" }) as { schemas: Record<string, Record<string, unknown>> };
    for (const c of COMPONENTS.filter((x) => x.io === io)) {
      const { $schema: _s, $id: _i, ...rest } = r.schemas[c.name];
      out[c.name] = rest;
    }
  }
  return out;
}

export function buildOpenApi(): Record<string, unknown> {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const op of OPERATIONS) {
    const params: Record<string, unknown>[] = (op.params ?? []).map((p) => ({ name: p.name, in: p.in, required: p.in === "path" ? true : !!p.required, description: p.description, schema: p.schema }));
    if (op.idempotent) params.push({ $ref: "#/components/parameters/IdempotencyKey" });
    const responses: Record<string, unknown> = {
      [String(op.ok.status)]: { description: op.ok.description, ...(op.ok.ref ? { content: { [op.ok.contentType ?? "application/json"]: { schema: ref(op.ok.ref) } } } : op.ok.contentType ? { content: { [op.ok.contentType]: { schema: { type: "string" } } } } : {}) },
      "400": { $ref: "#/components/responses/BadRequest" },
      "401": { $ref: "#/components/responses/Unauthorized" },
      "403": { $ref: "#/components/responses/Forbidden" },
      "404": { $ref: "#/components/responses/NotFound" },
      "429": { $ref: "#/components/responses/RateLimited" },
      "503": { $ref: "#/components/responses/Unavailable" },
    };
    if (op.idempotent) responses["409"] = { $ref: "#/components/responses/Conflict" };
    paths[op.path] ??= {};
    paths[op.path][op.method] = {
      operationId: op.id, summary: op.summary, tags: [op.tag],
      security: [op.subject ? { serviceToken: [], subjectAssertion: [] } : { serviceToken: [] }],
      "x-cyrus-status": op.status, "x-cyrus-scopes": op.scopes, "x-cyrus-subject": op.subject,
      ...(params.length ? { parameters: params } : {}),
      ...(op.body ? { requestBody: { required: true, content: { "application/json": { schema: op.body.ref ? ref(op.body.ref) : op.body.schema } } } } : {}),
      responses,
    };
  }
  const webhooks: Record<string, unknown> = {};
  for (const ev of WEBHOOK_EVENTS) {
    webhooks[ev] = { post: {
      operationId: `webhook_${ev.replace(".", "_")}`, summary: `Cyrus -> caller: ${ev}`, "x-cyrus-status": "planned",
      parameters: [
        { name: "Cyrus-Webhook-Id", in: "header", required: true, description: "event id; remember for 24 h, drop repeats", schema: { type: "string" } },
        { name: "Cyrus-Webhook-Timestamp", in: "header", required: true, description: "unix seconds; reject older than 300 s", schema: { type: "string" } },
        { name: "Cyrus-Signature", in: "header", required: true, description: "v1=<hex HMAC-SHA256(webhook secret, id + '.' + timestamp + '.' + raw body)>", schema: { type: "string" } },
      ],
      requestBody: { required: true, content: { "application/json": { schema: ref(WEBHOOK_COMPONENT[ev]) } } },
      responses: { "2XX": { description: "accepted (any 2xx); anything else is retried with backoff" } },
