      { name: "kind", in: "query", description: "asset kind", schema: { type: "string" } },
      { name: "game", in: "query", description: "game id for fit ranking", schema: { type: "string", pattern: "^[a-z][a-z0-9-]{1,31}$" } },
      { name: "minQuality", in: "query", description: "minimum quality score (default 40)", schema: { type: "integer", minimum: 0, maximum: 100 } },
      { name: "limit", in: "query", description: "page size (1-20, default 10)", schema: { type: "integer", minimum: 1, maximum: 20 } },
      cursor,
    ],
    ok: { status: 200, ref: "CatalogSearch", description: "one page of hits" } },
  { id: "getCatalogEntry", method: "get", path: "/catalog/entries/{entryId}", tag: "catalog", status: "live", scopes: ["catalog:read"], subject: true,
    summary: "One catalog entry (public fields). An entry the plan may not use answers 404.", params: [pathId("entryId", ENTRY_ID_PATTERN)],
    ok: { status: 200, ref: "CatalogEntry", description: "the entry" } },
  { id: "listMods", method: "get", path: "/mods", tag: "mods", status: "planned", scopes: ["mods:read"], subject: false,
    summary: "Published mod listings.", params: [limit, cursor], ok: { status: 200, description: "one page" } },
  { id: "getMod", method: "get", path: "/mods/{slug}", tag: "mods", status: "planned", scopes: ["mods:read"], subject: false,
    summary: "One published mod listing.", params: [pathId("slug", "^[a-z0-9-]{2,80}$")], ok: { status: 200, description: "the listing" } },
  { id: "getAccountPlan", method: "get", path: "/account/plan", tag: "account", status: "planned", scopes: ["account:read"], subject: true,
    summary: "The subject's plan tier and token balance.", ok: { status: 200, ref: "AccountPlan", description: "plan" } },
];

const WEBHOOK_COMPONENT: Record<(typeof WEBHOOK_EVENTS)[number], string> = {
  "build.finished": "WebhookBuildFinished", "mod.published": "WebhookModPublished", "install.result": "WebhookInstallResult",
  "delivery.rolledback": "WebhookDeliveryRolledBack", "library.contributed": "WebhookLibraryContributed",
};

/** app/api/cyrus/v1 route file that answers an operation path. */
export const handlerFileFor = (path: string) => `app/api/cyrus/v1${path.replace(/\{([A-Za-z]+)\}/g, "[$1]")}/route.ts`;

const errorResponse = (description: string) => ({ description, content: { "application/json": { schema: ref("Error") } } });

/** Zod components -> JSON Schema (draft 2020-12, which OpenAPI 3.1 uses), cross-referenced by name. */
export function componentSchemas(): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const io of ["output", "input"] as const) {
    const reg = z.registry<{ id: string }>();
    for (const c of COMPONENTS.filter((x) => x.io === io)) reg.add(c.schema, { id: c.name });
    const r = z.toJSONSchema(reg, { io, uri: (id) => `#/components/schemas/${id}`, unrepresentable: "any" }) as { schemas: Record<string, Record<string, unknown>> };
    for (const c of COMPONENTS.filter((x) => x.io === io)) {
      const { $schema: _s, $id: _i, ...rest } = r.schemas[c.name];
      out[c.name] = rest;
    }
  }
  return out;
}

export function buildOpenApi(): Record<string, unknown> {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const op of OPERATIONS) {
    const params: Record<string, unknown>[] = (op.params ?? []).map((p) => ({ name: p.name, in: p.in, required: p.in === "path" ? true : !!p.required, description: p.description, schema: p.schema }));
    if (op.idempotent) params.push({ $ref: "#/components/parameters/IdempotencyKey" });
    const responses: Record<string, unknown> = {
      [String(op.ok.status)]: { description: op.ok.description, ...(op.ok.ref ? { content: { [op.ok.contentType ?? "application/json"]: { schema: ref(op.ok.ref) } } } : op.ok.contentType ? { content: { [op.ok.contentType]: { schema: { type: "string" } } } } : {}) },
      "400": { $ref: "#/components/responses/BadRequest" },
      "401": { $ref: "#/components/responses/Unauthorized" },
      "403": { $ref: "#/components/responses/Forbidden" },
      "404": { $ref: "#/components/responses/NotFound" },
      "429": { $ref: "#/components/responses/RateLimited" },
      "503": { $ref: "#/components/responses/Unavailable" },
    };
    if (op.idempotent) responses["409"] = { $ref: "#/components/responses/Conflict" };
    paths[op.path] ??= {};
    paths[op.path][op.method] = {
      operationId: op.id, summary: op.summary, tags: [op.tag],
      security: [op.subject ? { serviceToken: [], subjectAssertion: [] } : { serviceToken: [] }],
      "x-cyrus-status": op.status, "x-cyrus-scopes": op.scopes, "x-cyrus-subject": op.subject,
      ...(params.length ? { parameters: params } : {}),
      ...(op.body ? { requestBody: { required: true, content: { "application/json": { schema: op.body.ref ? ref(op.body.ref) : op.body.schema } } } } : {}),
      responses,
    };
  }
  const webhooks: Record<string, unknown> = {};
  for (const ev of WEBHOOK_EVENTS) {
    webhooks[ev] = { post: {
      operationId: `webhook_${ev.replace(".", "_")}`, summary: `Cyrus -> caller: ${ev}`, "x-cyrus-status": "planned",
      parameters: [
        { name: "Cyrus-Webhook-Id", in: "header", required: true, description: "event id; remember for 24 h, drop repeats", schema: { type: "string" } },
        { name: "Cyrus-Webhook-Timestamp", in: "header", required: true, description: "unix seconds; reject older than 300 s", schema: { type: "string" } },
        { name: "Cyrus-Signature", in: "header", required: true, description: "v1=<hex HMAC-SHA256(webhook secret, id + '.' + timestamp + '.' + raw body)>", schema: { type: "string" } },
      ],
      requestBody: { required: true, content: { "application/json": { schema: ref(WEBHOOK_COMPONENT[ev]) } } },
