// A tiny, dependency-free YAML writer for the generated OpenAPI file, plus a reader for exactly what it writes
// (block mappings and sequences, JSON-quoted strings, numbers, booleans, null, {} and []). Every string is written as
// a JSON string, which is a valid YAML 1.2 double-quoted scalar, so any YAML parser reads the file. Pure.

const PLAIN_KEY = /^[A-Za-z_][A-Za-z0-9_-]*$/;
const RESERVED = /^(true|false|null|yes|no|on|off|y|n|~)$/i;
const key = (k: string) => (PLAIN_KEY.test(k) && !RESERVED.test(k) ? k : JSON.stringify(k));

function scalar(v: unknown): string {
  if (v === null || v === undefined) return "null";
  if (typeof v === "string") return JSON.stringify(v);
  if (typeof v === "number") { if (!Number.isFinite(v)) throw new Error("yaml: non-finite number"); return String(v); }
  if (typeof v === "boolean") return v ? "true" : "false";
  throw new Error(`yaml: cannot write ${typeof v}`);
}
const isBlock = (v: unknown) => (Array.isArray(v) ? v.length > 0 : !!v && typeof v === "object" && Object.keys(v).length > 0);
const inline = (v: unknown) => (Array.isArray(v) ? "[]" : v && typeof v === "object" ? "{}" : scalar(v));

function lines(v: unknown, ind: number): string[] {
  const pad = " ".repeat(ind);
  const out: string[] = [];
  if (Array.isArray(v)) {
    for (const item of v) {
      if (!isBlock(item)) { out.push(`${pad}- ${inline(item)}`); continue; }
      const sub = lines(item, ind + 2);
      out.push(`${pad}- ${sub[0].slice(ind + 2)}`, ...sub.slice(1));
    }
  } else {
    for (const [k, val] of Object.entries(v as Record<string, unknown>)) {
      if (val === undefined) continue;
      if (!isBlock(val)) out.push(`${pad}${key(k)}: ${inline(val)}`);
      else out.push(`${pad}${key(k)}:`, ...lines(val, ind + 2));
    }
  }
  return out;
}

export function toYaml(doc: Record<string, unknown>, header = ""): string {
  return (header ? header.split("\n").map((l) => `# ${l}`.trimEnd()).join("\n") + "\n" : "") + lines(doc, 0).join("\n") + "\n";
}

// ------------------------------------------------------------------------------------------------ reader
type Line = { ind: number; text: string; no: number };

function parseScalar(s: string, no: number): unknown {
  const t = s.trim();
  if (t === "{}") return {};
  if (t === "[]") return [];
  if (t === "null" || t === "~") return null;
  if (t === "true") return true;
  if (t === "false") return false;
  if (t.startsWith('"')) return JSON.parse(t);
  if (/^-?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(t)) return Number(t);
  throw new Error(`yaml line ${no}: unsupported scalar ${t}`);
}

/** Split "key: rest" (key plain or JSON-quoted). */
function splitKey(text: string, no: number): [string, string] {
  if (text.startsWith('"')) {
    let i = 1;
    while (i < text.length && text[i] !== '"') i += text[i] === "\\" ? 2 : 1;
    const k = JSON.parse(text.slice(0, i + 1)) as string;
    const rest = text.slice(i + 1);
    if (!rest.startsWith(":")) throw new Error(`yaml line ${no}: expected ':'`);
    return [k, rest.slice(1).trim()];
  }
  const m = /^([A-Za-z_][A-Za-z0-9_-]*):(?:\s(.*))?$/.exec(text);
  if (!m) throw new Error(`yaml line ${no}: expected key: value, got ${text}`);
  return [m[1], (m[2] ?? "").trim()];
}

function parseBlock(ls: Line[], i: number, ind: number): [unknown, number] {
  if (ls[i].text.startsWith("- ") || ls[i].text === "-") {
    const arr: unknown[] = [];
    while (i < ls.length && ls[i].ind === ind && ls[i].text.startsWith("-")) {
      const rest = ls[i].text.slice(1).trim();
      if (rest.includes(": ") || /^[A-Za-z_"][^:]*:$/.test(rest) || (rest.startsWith('"') && /":(\s|$)/.test(rest))) {
        // an inline first key of a mapping item: re-read it as a line at ind + 2
        const copy = ls.slice(); copy[i] = { ind: ind + 2, text: rest, no: ls[i].no };
        const [v, j] = parseBlock(copy, i, ind + 2);
        arr.push(v); i = j;
      } else if (rest.startsWith("- ")) {
        const copy = ls.slice(); copy[i] = { ind: ind + 2, text: rest, no: ls[i].no };
        const [v, j] = parseBlock(copy, i, ind + 2);
        arr.push(v); i = j;
      } else { arr.push(parseScalar(rest, ls[i].no)); i++; }
    }
    return [arr, i];
  }
  const obj: Record<string, unknown> = {};
  while (i < ls.length && ls[i].ind === ind && !ls[i].text.startsWith("- ")) {
    const [k, rest] = splitKey(ls[i].text, ls[i].no);
    if (k in obj) throw new Error(`yaml line ${ls[i].no}: duplicate key ${k}`);
    if (rest) { obj[k] = parseScalar(rest, ls[i].no); i++; continue; }
    i++;
    if (i >= ls.length || ls[i].ind <= ind) throw new Error(`yaml line ${ls[i - 1].no}: empty value for ${k}`);
    const [v, j] = parseBlock(ls, i, ls[i].ind);
    obj[k] = v; i = j;
  }
  return [obj, i];
}

export function fromYaml(text: string): unknown {
  const ls: Line[] = [];
  text.split("\n").forEach((raw, n) => {
    if (!raw.trim() || raw.trimStart().startsWith("#")) return;
    if (raw.includes("\t")) throw new Error(`yaml line ${n + 1}: tab`);
    const ind = raw.length - raw.trimStart().length;
    ls.push({ ind, text: raw.trim(), no: n + 1 });
  });
  if (!ls.length) return null;
  const [v, i] = parseBlock(ls, 0, ls[0].ind);
  if (i !== ls.length) throw new Error(`yaml line ${ls[i].no}: unexpected indentation`);
  return v;
}

