// Cyrus API v1 contract: docs/api/cyrus-v1.openapi.yaml is (1) exactly what the generator writes from the Zod sources,
// (2) readable YAML (own reader + PyYAML when present) equal to the built document, (3) structurally valid OpenAPI 3.1
// (refs resolve, path params match, unique operationIds, known statuses), and (4) honest: every "live" operation has a
// handler under app/api/cyrus/v1 exporting that method, no "planned" one does, and no handler is undocumented.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";
import { buildOpenApi, handlerFileFor, OPERATIONS } from "../lib/cyrus/api/v1/openapi";
import { openApiYaml } from "../lib/cyrus/api/v1/contract-file";
import { fromYaml, toYaml } from "../lib/cyrus/api/v1/yaml";
import { SCOPES } from "../lib/cyrus/api/v1/scopes";

const ROOT = path.resolve(__dirname, "..");
const FILE = path.join(ROOT, "docs", "api", "cyrus-v1.openapi.yaml");
const API_DIR = path.join(ROOT, "app", "api", "cyrus", "v1");
const METHODS = ["get", "post", "put", "patch", "delete"] as const;
const norm = (v: unknown) => JSON.parse(JSON.stringify(v));

function walk(v: unknown, f: (node: Record<string, unknown>, at: string) => void, at = "#"): void {
  if (Array.isArray(v)) v.forEach((x, i) => walk(x, f, `${at}/${i}`));
  else if (v && typeof v === "object") {
    f(v as Record<string, unknown>, at);
    for (const [k, x] of Object.entries(v)) walk(x, f, `${at}/${k}`);
  }
}
const resolve = (doc: Record<string, unknown>, ref: string): unknown =>
  ref.replace(/^#\//, "").split("/").reduce<unknown>((o, k) => (o && typeof o === "object" ? (o as Record<string, unknown>)[k.replace(/~1/g, "/").replace(/~0/g, "~")] : undefined), doc);

describe("Cyrus API v1 OpenAPI file", () => {
  const text = readFileSync(FILE, "utf8");
  const doc = buildOpenApi();

  it("is exactly the generator's output (run npx tsx tools/cyrus-api/gen-openapi.ts after changing lib/cyrus/api/v1)", () => {
    assert.equal(text, openApiYaml());
  });
  it("reads back (own YAML reader) to the built document", () => {
    assert.deepEqual(fromYaml(text), norm(doc));
  });
  it("reads back with PyYAML too, when python3 + yaml are installed", (t) => {
    const r = spawnSync("python3", ["-c", "import json,sys,yaml; print(json.dumps(yaml.safe_load(open(sys.argv[1]))))", FILE], { encoding: "utf8" });
    if (r.status !== 0) { t.skip(`python3/yaml not available: ${(r.stderr || "").split("\n").pop()}`); return; }
    assert.deepEqual(JSON.parse(r.stdout), norm(doc));
  });
  it("yaml writer round-trips awkward values", () => {
    const v = { "200": { a: "x: y", b: ["- not a list", "", "#hash"], "$ref": "#/a", c: [[1, 2], [{ d: null, e: true }]], f: {}, g: [], "true": -1.5, h: "line\nbreak \u0001" } };
    assert.deepEqual(fromYaml(toYaml(v)), v);
  });

  it("is structurally valid OpenAPI 3.1", () => {
    assert.match(String(doc.openapi), /^3\.1\.\d+$/);
    const info = doc.info as Record<string, unknown>;
    assert.equal(typeof info.title, "string"); assert.match(String(info.version), /^\d+\.\d+\.\d+$/);
    const tags = new Set((doc.tags as { name: string }[]).map((t) => t.name));
    const comps = doc.components as Record<string, Record<string, unknown>>;
    const ids = new Set<string>();
    for (const [p, item] of Object.entries(doc.paths as Record<string, Record<string, Record<string, unknown>>>)) {
      assert.match(p, /^\/[a-z0-9/{}A-Z-]*$/, p);
      const templ = [...p.matchAll(/\{([A-Za-z]+)\}/g)].map((m) => m[1]).sort();
      for (const [m, op] of Object.entries(item)) {
        assert.ok((METHODS as readonly string[]).includes(m), `${p} ${m}`);
        assert.ok(!ids.has(op.operationId as string), `duplicate operationId ${op.operationId}`); ids.add(op.operationId as string);
        const pathParams = ((op.parameters ?? []) as Record<string, unknown>[]).filter((x) => x.in === "path");
        assert.deepEqual(pathParams.map((x) => x.name).sort(), templ, `${op.operationId}: path params match the template`);
        for (const x of pathParams) assert.equal(x.required, true);
        for (const t of op.tags as string[]) assert.ok(tags.has(t), `tag ${t} declared`);
        assert.ok(["live", "planned"].includes(op["x-cyrus-status"] as string));
        for (const s of op["x-cyrus-scopes"] as string[]) assert.ok((SCOPES as readonly string[]).includes(s), `scope ${s}`);
        const codes = Object.keys(op.responses as object);
        assert.ok(codes.some((c) => /^[23]/.test(c)), `${op.operationId} has a success response`);
        for (const sec of op.security as Record<string, unknown>[]) for (const k of Object.keys(sec)) assert.ok(comps.securitySchemes[k], `security ${k}`);
      }
    }
    // every $ref resolves; required names are declared properties
    walk(doc, (node, at) => {
      if (typeof node.$ref === "string") assert.ok(resolve(doc, node.$ref) !== undefined, `${at}: ${node.$ref} resolves`);
      if (Array.isArray(node.required) && node.properties && typeof node.properties === "object") {
        for (const r of node.required) assert.ok(r in (node.properties as object), `${at}: required ${r} is a property`);
      }
      if (typeof node.type === "string") assert.ok(["object", "array", "string", "number", "integer", "boolean", "null"].includes(node.type), `${at}: type ${node.type}`);
    });
    for (const name of ["Error", "Issue", "ModSpec", "ModSpecInput", "CatalogEntry", "MotionSpecInput", "Build", "ProjectDetail"]) assert.ok(comps.schemas[name], `component ${name}`);
  });

  it("reuses the engine's structured issue shape for errors", () => {
    const s = (doc.components as Record<string, Record<string, Record<string, unknown>>>).schemas;
    assert.deepEqual((s.Issue.required as string[]).sort(), ["code", "message", "path"]);
    const err = (s.Error.properties as Record<string, Record<string, unknown>>).error;
    assert.deepEqual(((err.properties as Record<string, Record<string, unknown>>).issues.items as Record<string, unknown>).$ref, "#/components/schemas/Issue");
  });

  it("documents the five webhooks, all planned, all signed", () => {
    const w = doc.webhooks as Record<string, { post: Record<string, unknown> }>;
    assert.deepEqual(Object.keys(w).sort(), ["build.finished", "delivery.rolledback", "install.result", "library.contributed", "mod.published"]);
    for (const [k, v] of Object.entries(w)) {
      assert.equal(v.post["x-cyrus-status"], "planned", k);
      assert.ok((v.post.parameters as { name: string }[]).some((p) => p.name === "Cyrus-Signature"));
    }
  });
});

describe("Cyrus API v1 operations map to handlers", () => {
  const exportsOf = (file: string) => new Set([...readFileSync(file, "utf8").matchAll(/export\s+(?:async\s+)?(?:function|const)\s+(GET|POST|PUT|PATCH|DELETE)\b/g)].map((m) => m[1].toLowerCase()));

  for (const op of OPERATIONS) {
    it(`${op.status === "live" ? "live" : "planned"}: ${op.method.toUpperCase()} ${op.path} (${op.id})`, () => {
      const f = path.join(ROOT, handlerFileFor(op.path));
      const has = existsSync(f) && exportsOf(f).has(op.method);
      if (op.status === "live") assert.ok(has, `${handlerFileFor(op.path)} must export ${op.method.toUpperCase()}`);
      else assert.ok(!has, `${op.id} is answered by ${handlerFileFor(op.path)}: mark it live`);
    });
  }

  it("no handler under app/api/cyrus/v1 is undocumented", () => {
    if (!existsSync(API_DIR)) return;
    const files: string[] = [];
    const rec = (d: string) => { for (const n of readdirSync(d)) { const p = path.join(d, n); if (statSync(p).isDirectory()) rec(p); else if (n === "route.ts") files.push(p); } };
    rec(API_DIR);
    const documented = new Set(OPERATIONS.filter((o) => o.status === "live").map((o) => `${handlerFileFor(o.path)} ${o.method}`));
    for (const f of files) for (const m of exportsOf(f)) {
      const rel = path.relative(ROOT, f).split(path.sep).join("/");
      assert.ok(documented.has(`${rel} ${m}`), `${rel} exports ${m.toUpperCase()} but no live operation documents it`);
    }
  });
});

