    if (t !== undefined && t > nowMs) return true;
    if (this.m.size >= this.max) {
      for (const [k, exp] of this.m) { if (exp <= nowMs || this.m.size >= this.max) this.m.delete(k); else break; }
    }
    this.m.set(id, expiresAtMs);
    return false;
  }
  get size() { return this.m.size; }
}

// ------------------------------------------------------------------------------------------------ subject assertions
export const SUBJECT_AUD = "cyrus-api-v1";
export const SUBJECT_MAX_LIFETIME_S = 120;
export const SUBJECT_SKEW_S = 30;
/** Opaque, stable account id (today the Nxeon user id; later an SSO sub). "@" is refused so an email can never be one. */
export const SUBJECT_RE = /^[A-Za-z0-9_:.-]{4,128}$/;
export type SubjectClaims = { v: 1; iss: string; sub: string; aud: string; iat: number; exp: number; jti: string; kid?: string };
export type SubjectKey = { client: string; kid: string; publicKey: KeyObject };

export function mintSubjectAssertion(claims: SubjectClaims, privateKey: KeyObject): string {
  const p = b64u(JSON.stringify(claims));
  return `${p}.${b64u(edSign(null, Buffer.from(p), privateKey))}`;
}

export type SubjectCheck = { ok: true; claims: SubjectClaims } | { ok: false; code: "bad_subject"; message: string };
export function verifySubjectAssertion(raw: string | null | undefined, o: { client: string; keys: readonly SubjectKey[]; nowMs: number; replay: ReplayCache }): SubjectCheck {
  const bad = (message: string): SubjectCheck => ({ ok: false, code: "bad_subject", message });
  const s = String(raw ?? "").trim();
  if (!s || s.length > 2048) return bad("subject assertion missing or too long");
  const [p, sig, extra] = s.split(".");
  if (!p || !sig || extra !== undefined) return bad("subject assertion is not payload.signature");
  let c: Record<string, unknown>;
  try { c = JSON.parse(Buffer.from(p, "base64url").toString("utf8")); } catch { return bad("subject payload is not JSON"); }
  if (!c || typeof c !== "object" || Array.isArray(c)) return bad("subject payload is not an object");
  if ("email" in c) return bad("subject assertions carry a stable subject id, never an email");
  if (c.iss !== o.client) return bad("subject issuer is not the calling client");
  const keys = o.keys.filter((k) => k.client === o.client && (c.kid === undefined || k.kid === c.kid));
  const sigBuf = Buffer.from(sig, "base64url");
  if (!keys.some((k) => { try { return edVerify(null, Buffer.from(p), k.publicKey, sigBuf); } catch { return false; } })) return bad("subject signature does not verify");
  if (c.v !== 1) return bad("unsupported subject version");
  if (c.aud !== SUBJECT_AUD) return bad("wrong audience");
  if (typeof c.sub !== "string" || !SUBJECT_RE.test(c.sub)) return bad("subject id is not a stable opaque id");
  if (typeof c.jti !== "string" || !/^[A-Za-z0-9_-]{8,64}$/.test(c.jti)) return bad("subject jti missing");
  const iat = Number(c.iat), exp = Number(c.exp), now = Math.floor(o.nowMs / 1000);
  if (!Number.isInteger(iat) || !Number.isInteger(exp) || exp <= iat) return bad("subject times are invalid");
  if (exp - iat > SUBJECT_MAX_LIFETIME_S) return bad(`subject lifetime exceeds ${SUBJECT_MAX_LIFETIME_S} s`);
  if (iat > now + SUBJECT_SKEW_S) return bad("subject issued in the future");
  if (exp + SUBJECT_SKEW_S < now) return bad("subject expired");
  if (o.replay.seen(`sub:${o.client}:${c.jti}`, (exp + SUBJECT_SKEW_S) * 1000, o.nowMs)) return bad("subject assertion already used");
  return { ok: true, claims: c as unknown as SubjectClaims };
}

// ------------------------------------------------------------------------------------------------ request signing (HMAC)
export const SIG_HEADERS = { keyId: "cyrus-key-id", ts: "cyrus-timestamp", nonce: "cyrus-nonce", sig: "cyrus-signature" } as const;
export const REQUEST_SKEW_S = 300;
export const canonicalRequest = (method: string, pathWithQuery: string, ts: string, nonce: string, body: string | Buffer) =>
  [method.toUpperCase(), pathWithQuery, ts, nonce, sha256Hex(body)].join("\n");

export function signRequest(a: { keyId: string; secret: string; method: string; pathWithQuery: string; body: string | Buffer; nowMs: number; nonce?: string }): Record<string, string> {
  const ts = String(Math.floor(a.nowMs / 1000));
  const nonce = a.nonce ?? randomBytes(12).toString("base64url");
  const sig = createHmac("sha256", a.secret).update(canonicalRequest(a.method, a.pathWithQuery, ts, nonce, a.body)).digest("hex");
  return { [SIG_HEADERS.keyId]: a.keyId, [SIG_HEADERS.ts]: ts, [SIG_HEADERS.nonce]: nonce, [SIG_HEADERS.sig]: `v1=${sig}` };
}

export type RequestCheck = { ok: true; keyId: string } | { ok: false; code: "unsigned" | "unknown_key" | "stale" | "replay" | "bad_signature" };
export function verifyRequest(a: { header: (name: string) => string | null; method: string; pathWithQuery: string; body: string | Buffer; secretFor: (keyId: string) => string | null; nowMs: number; replay: ReplayCache }): RequestCheck {
  const keyId = a.header(SIG_HEADERS.keyId), ts = a.header(SIG_HEADERS.ts), nonce = a.header(SIG_HEADERS.nonce), sig = a.header(SIG_HEADERS.sig);
  if (!keyId || !ts || !nonce || !sig || !/^\d{9,11}$/.test(ts) || !/^[A-Za-z0-9_-]{8,64}$/.test(nonce)) return { ok: false, code: "unsigned" };
  const secret = a.secretFor(keyId);
  if (!secret) return { ok: false, code: "unknown_key" };
  if (Math.abs(Math.floor(a.nowMs / 1000) - Number(ts)) > REQUEST_SKEW_S) return { ok: false, code: "stale" };
  const want = `v1=${createHmac("sha256", secret).update(canonicalRequest(a.method, a.pathWithQuery, ts, nonce, a.body)).digest("hex")}`;
  if (!safeEqual(sig, want)) return { ok: false, code: "bad_signature" };
  if (a.replay.seen(`req:${keyId}:${nonce}`, (Number(ts) + REQUEST_SKEW_S) * 1000, a.nowMs)) return { ok: false, code: "replay" };
  return { ok: true, keyId };
}

// ------------------------------------------------------------------------------------------------ webhooks
export const WEBHOOK_TOLERANCE_S = 300;
export const signWebhook = (secret: string, id: string, timestamp: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${timestamp}.${body}`).digest("hex")}`;

/** Receiver side (what Nxeon runs): signature, freshness, then exactly-once by id. */
export function verifyWebhook(a: { secret: string; id: string | null; timestamp: string | null; body: string; signature: string | null; nowMs: number; replay: ReplayCache }): { ok: true } | { ok: false; code: "unsigned" | "stale" | "bad_signature" | "duplicate" } {
  if (!a.id || !a.timestamp || !a.signature || !/^\d{9,11}$/.test(a.timestamp)) return { ok: false, code: "unsigned" };
  if (Math.abs(Math.floor(a.nowMs / 1000) - Number(a.timestamp)) > WEBHOOK_TOLERANCE_S) return { ok: false, code: "stale" };
  // several "v1=" values may be sent during a secret rotation
  const want = signWebhook(a.secret, a.id, a.timestamp, a.body);
  if (!a.signature.split(/[ ,]+/).some((s) => safeEqual(s, want))) return { ok: false, code: "bad_signature" };
  if (a.replay.seen(`wh:${a.id}`, a.nowMs + 24 * 3600_000, a.nowMs)) return { ok: false, code: "duplicate" };
  return { ok: true };
}

