// Cyrus API v1 configuration, from the environment (Cyrus-owned names). SERVER ONLY. Fails CLOSED: off unless
// CYRUS_API_V1 is on; a malformed key list makes every request 503 (never "no auth").
//   CYRUS_API_V1=1                     the flag (default off: every /api/cyrus/v1 route answers 404)
//   CYRUS_API_V1_KEYS=[{"id":"nxeon01","client":"nxeon","sha256":"<hex of the secret>","scopes":["projects:read"],"rpm":120}]
//   CYRUS_API_V1_SUBJECT_KEYS=[{"client":"nxeon","kid":"s1","publicKey":"<base64 DER SPKI Ed25519>"}]
//   CYRUS_API_V1_CATALOG_FILE=/path/entries.jsonl   (optional; CatalogEntry v1 per line; until the catalog has a DB index)
import { createPublicKey } from "node:crypto";
import { isTrue } from "../../host/types";
import { isScope, type Scope } from "./scopes";
import type { SubjectKey } from "./signing";

export type ApiKey = { id: string; client: string; sha256: string; scopes: Scope[]; rpm: number };
export type ApiV1Config = {
  enabled: boolean;
  /** set when the config cannot be trusted: every request answers 503 */
  error: string | null;
  keys: ApiKey[];
  subjectKeys: SubjectKey[];
  catalogFile: string | null;
};

export const DEFAULT_RPM = 120;
const CLIENT_RE = /^[a-z][a-z0-9-]{1,31}$/;

function parseList(raw: string | undefined, name: string): unknown[] {
  if (!raw || !raw.trim()) return [];
  const v = JSON.parse(raw);
  if (!Array.isArray(v)) throw new Error(`${name} must be a JSON array`);
  return v;
}

let cache: { raw: string; cfg: ApiV1Config } | null = null;

export function apiV1Config(env: Record<string, string | undefined> = process.env): ApiV1Config {
  const raw = [env.CYRUS_API_V1, env.CYRUS_API_V1_KEYS, env.CYRUS_API_V1_SUBJECT_KEYS, env.CYRUS_API_V1_CATALOG_FILE].join("\u0000");
  if (cache && cache.raw === raw) return cache.cfg;
  const cfg: ApiV1Config = { enabled: isTrue(env.CYRUS_API_V1), error: null, keys: [], subjectKeys: [], catalogFile: env.CYRUS_API_V1_CATALOG_FILE?.trim() || null };
  try {
    const ids = new Set<string>();
    for (const k of parseList(env.CYRUS_API_V1_KEYS, "CYRUS_API_V1_KEYS")) {
      const o = (k ?? {}) as Record<string, unknown>;
      if (typeof o.id !== "string" || !/^[a-z0-9]{4,32}$/.test(o.id)) throw new Error("a key id must be 4-32 lowercase letters/digits");
      if (ids.has(o.id)) throw new Error(`duplicate key id ${o.id}`);
      if (typeof o.client !== "string" || !CLIENT_RE.test(o.client)) throw new Error(`key ${o.id}: bad client`);
      if (typeof o.sha256 !== "string" || !/^[0-9a-f]{64}$/.test(o.sha256)) throw new Error(`key ${o.id}: sha256 must be 64 hex`);
      const rpm = o.rpm === undefined ? DEFAULT_RPM : Number(o.rpm);
      if (!Number.isInteger(rpm) || rpm < 1 || rpm > 10_000) throw new Error(`key ${o.id}: rpm must be 1-10000`);
      ids.add(o.id);
      cfg.keys.push({ id: o.id, client: o.client, sha256: o.sha256, scopes: (Array.isArray(o.scopes) ? o.scopes : []).filter(isScope), rpm });
    }
    for (const k of parseList(env.CYRUS_API_V1_SUBJECT_KEYS, "CYRUS_API_V1_SUBJECT_KEYS")) {
      const o = (k ?? {}) as Record<string, unknown>;
      if (typeof o.client !== "string" || !CLIENT_RE.test(o.client)) throw new Error("subject key: bad client");
      if (typeof o.kid !== "string" || !/^[A-Za-z0-9_-]{1,32}$/.test(o.kid)) throw new Error("subject key: bad kid");
      if (typeof o.publicKey !== "string") throw new Error(`subject key ${o.kid}: publicKey missing`);
      const publicKey = createPublicKey({ key: Buffer.from(o.publicKey, "base64"), format: "der", type: "spki" });
      if (publicKey.asymmetricKeyType !== "ed25519") throw new Error(`subject key ${o.kid}: must be Ed25519`);
      cfg.subjectKeys.push({ client: o.client, kid: o.kid, publicKey });
    }
  } catch (e) {
    cfg.error = (e as Error).message || "bad CYRUS_API_V1 config";
    cfg.keys = []; cfg.subjectKeys = [];
  }
  cache = { raw, cfg };
  return cfg;
}

