// Cyrus API v1: the framework-free handlers (Request -> Response) of the LIVE operations in ./openapi.ts. Read-only.
// app/api/cyrus/v1/** are one-line wrappers with v1Deps() (./deps.ts); tests pass fakes. Every request:
//   flag (off = 404, as if the route did not exist) -> config sane (else 503) -> service token (401) -> scopes (403)
//   -> rate limit per key (429) -> subject assertion when the operation is per-user (400/401) -> handler.
// Objects that are not the subject's answer 404, exactly like unknown ones. Errors: {error:{code,message,issues?,requestId}}.
// HOST SEAM: no Nxeon imports (data comes through V1Deps).
import { randomBytes } from "node:crypto";
import { access as catalogAccess } from "../../library/v2/tools";
import { CATALOG_KINDS, catalogRef, type CatalogEntry, type CatalogKind } from "../../library/v2/entry";
import type { CatalogIndex } from "../../library/v2/retrieval";
import { API_VERSION, type ApiIssue } from "./schemas";
import { BUILD_ID_PATTERN, ENTRY_ID_PATTERN, OPERATIONS, PROJECT_ID_PATTERN, type Operation } from "./openapi";
import type { ApiKey, ApiV1Config } from "./config";
import { parseServiceToken, safeEqual, sha256Hex, verifySubjectAssertion, type ReplayCache } from "./signing";

export type LiveOperationId = "getHealth" | "listProjects" | "getProject" | "getBuild" | "searchCatalog" | "getCatalogEntry";

export type ProjectRow = { id: string; userId: string; game: string; namespace: string; title: string | null; rootBuildId: string | null; headRevisionId: string | null; lastPassingRevisionId: string | null; revisionCount: number; createdAt: Date; updatedAt: Date };
export type RevisionRow = { id: string; projectId: string; seq: number; kind: string; status: string; message: string | null; modBuildId: string | null; manifest: unknown; spec: unknown; createdAt: Date };
export type BuildRow = {
  id: string; userId: string; status: string; prompt: string; changeRequest: string | null; baseBuildId: string | null; rootBuildId: string | null;
  mcVersion: string; pluginName: string | null; version: string | null; result: unknown; error: string | null; errorCode: string | null; attempts: number;
  durationMs: number | null; jarName: string | null; jarSize: number | null; jarSha256: string | null; cyrus: unknown; createdAt: Date; updatedAt: Date; finishedAt: Date | null;
};

export type V1Deps = {
  config: () => ApiV1Config;
  now: () => Date;
  replay: ReplayCache;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec: number; remaining: number };
  store: {
    /** newest first; `after` = the last row of the previous page */
    listProjects(userId: string, limit: number, after: { createdAt: Date; id: string } | null): Promise<ProjectRow[]>;
    getProject(id: string): Promise<ProjectRow | null>;
    revisions(ids: string[]): Promise<RevisionRow[]>;
    getBuild(id: string): Promise<BuildRow | null>;
  };
  /** null = no catalog backend configured (503 catalog_unavailable) */
  catalog: () => Promise<CatalogIndex | null>;
  /** the subject's raw plan (asset-gate understands it); a throw = unknown = fail closed */
  planOf: (userId: string) => Promise<unknown>;
  proprietaryCleared: () => boolean;
  requestId?: () => string;
  log?: (msg: string) => void;
};

type Ctx = { requestId: string; headers: Record<string, string> };
const send = (ctx: Ctx, status: number, body: unknown, extra: Record<string, string> = {}) =>
  Response.json(body, { status, headers: { "cache-control": "no-store", "x-robots-tag": "noindex", "cyrus-api-version": API_VERSION, "cyrus-request-id": ctx.requestId, ...ctx.headers, ...extra } });
const fail = (ctx: Ctx, status: number, code: string, message: string, issues?: ApiIssue[], extra?: Record<string, string>) =>
  send(ctx, status, { error: { code, message, ...(issues?.length ? { issues } : {}), requestId: ctx.requestId } }, extra);
const iso = (d: Date | null) => (d ? d.toISOString() : null);

class BadInput extends Error { constructor(public issues: ApiIssue[]) { super("bad input"); } }
const issue = (path: string, message: string, code = "invalid"): ApiIssue => ({ path, code, message });

function intParam(u: URL, name: string, min: number, max: number, dflt: number): number {
  const raw = u.searchParams.get(name);
  if (raw === null || raw === "") return dflt;
  if (!/^\d{1,6}$/.test(raw) || Number(raw) < min || Number(raw) > max) throw new BadInput([issue(name, `${name} must be a whole number ${min}-${max}`)]);
  return Number(raw);
}
const encCursor = (o: Record<string, unknown>) => Buffer.from(JSON.stringify(o)).toString("base64url");
function decCursor<T>(raw: string | null, check: (o: Record<string, unknown>) => T | null): T | null {
  if (!raw) return null;
  try {
    if (raw.length > 200) throw new Error();
    const o = JSON.parse(Buffer.from(raw, "base64url").toString("utf8"));
    const v = o && typeof o === "object" ? check(o) : null;
    if (v) return v;
  } catch { /* falls through */ }
  throw new BadInput([issue("cursor", "cursor is not one this API returned")]);
}

// ------------------------------------------------------------------------------------------------ auth
type Caller = { key: ApiKey; subject: string | null };
type AuthOut = { ok: true; caller: Caller } | { ok: false; res: Response };

function authenticate(req: Request, op: Operation, cfg: ApiV1Config, deps: V1Deps, ctx: Ctx): AuthOut {
  const no = (res: Response): AuthOut => ({ ok: false, res });
  const h = req.headers.get("authorization") ?? "";
  const tok = parseServiceToken(h.startsWith("Bearer ") ? h.slice(7) : "");
  // unknown key and wrong secret look the same to the caller
  const key = tok ? cfg.keys.find((k) => k.id === tok.keyId) ?? null : null;
  if (!tok || !key || !safeEqual(sha256Hex(tok.secret), key.sha256)) return no(fail(ctx, 401, "unauthorized", "a valid Cyrus service token is required", undefined, { "www-authenticate": 'Bearer realm="cyrus-api-v1"' }));
  const missing = op.scopes.filter((s) => !key.scopes.includes(s));
  if (missing.length) return no(fail(ctx, 403, "forbidden_scope", `this token lacks ${missing.join(", ")}`));
  const rl = deps.rateLimit(`cyrus-api-v1:${key.id}`, key.rpm, 60_000);
  ctx.headers["ratelimit-limit"] = String(key.rpm);
  ctx.headers["ratelimit-remaining"] = String(Math.max(0, rl.remaining));
  if (!rl.ok) return no(fail(ctx, 429, "rate_limited", "too many requests for this token", undefined, { "retry-after": String(Math.max(1, rl.retryAfterSec)) }));
  if (!op.subject) return { ok: true, caller: { key, subject: null } };
  const raw = req.headers.get("cyrus-subject");
  if (!raw) return no(fail(ctx, 400, "subject_required", "this operation acts for one account: send the Cyrus-Subject assertion"));
  const v = verifySubjectAssertion(raw, { client: key.client, keys: cfg.subjectKeys, nowMs: deps.now().getTime(), replay: deps.replay });
  if (!v.ok) return no(fail(ctx, 401, v.code, v.message));
  return { ok: true, caller: { key, subject: v.claims.sub } };
}

// ------------------------------------------------------------------------------------------------ views
const files = (m: unknown) => (Array.isArray(m) ? m.length : 0);
export const revisionView = (r: RevisionRow) => ({ id: r.id, seq: r.seq, kind: r.kind, status: r.status, message: r.message, modBuildId: r.modBuildId, files: files(r.manifest), createdAt: iso(r.createdAt) });
export const projectView = (p: ProjectRow) => ({
  id: p.id, game: p.game, namespace: p.namespace, title: p.title, rootBuildId: p.rootBuildId, headRevisionId: p.headRevisionId,
  lastPassingRevisionId: p.lastPassingRevisionId, revisionCount: p.revisionCount, createdAt: iso(p.createdAt), updatedAt: iso(p.updatedAt),
});
const TERMINAL = new Set(["succeeded", "failed"]);
export function buildView(b: BuildRow) {
  const meta = (b.cyrus && typeof b.cyrus === "object" ? b.cyrus : {}) as Record<string, unknown>;
  const result = (b.result && typeof b.result === "object" ? b.result : {}) as Record<string, unknown>;
  return {
    id: b.id, status: b.status, terminal: TERMINAL.has(b.status),
    target: { game: typeof meta.game === "string" ? meta.game : "minecraft", version: b.mcVersion },
