// Real wiring of the Cyrus API v1 handlers (./http.ts). SERVER ONLY. HOST SEAM: Cyrus' own tables through cyrusDb, the
// rate limiter through the host, the plan through tokens tierOf (the same lookup the studios use), nothing from Nxeon.
import { readFileSync, statSync } from "node:fs";
import { cyrusDb } from "../../db";
import { getHost } from "../../host";
import { tierOf } from "../../tokens/access";
import { validateCatalogEntry } from "../../library/v2/entry";
import { createMemoryCatalogIndex, type CatalogIndex } from "../../library/v2/retrieval";
import { apiV1Config } from "./config";
import { ReplayCache } from "./signing";
import type { V1Deps } from "./http";

const replay = new ReplayCache();

/** Max bytes of CYRUS_API_V1_CATALOG_FILE read into memory (a stopgap until the catalog has a database index). */
export const CATALOG_FILE_MAX_BYTES = 64 * 1024 * 1024;
let catalogCache: { key: string; index: CatalogIndex } | null = null;

/** A memory index over a CatalogEntry JSONL file; invalid lines are skipped, a too-large or missing file = no catalog. */
export async function fileCatalog(file: string | null): Promise<CatalogIndex | null> {
  if (!file) return null;
  let st;
  try { st = statSync(file); } catch { return null; }
  if (!st.isFile() || st.size > CATALOG_FILE_MAX_BYTES) return null;
  const key = `${file}:${st.size}:${st.mtimeMs}`;
  if (catalogCache?.key === key) return catalogCache.index;
  const entries = [];
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue;
    try { const v = validateCatalogEntry(JSON.parse(line)); if (v.ok) entries.push(v.entry); } catch { /* skip */ }
  }
  const index = createMemoryCatalogIndex(entries);
  catalogCache = { key, index };
  return index;
}

const PROJECT_SELECT = { id: true, userId: true, game: true, namespace: true, title: true, rootBuildId: true, headRevisionId: true, lastPassingRevisionId: true, revisionCount: true, createdAt: true, updatedAt: true } as const;

export function v1Deps(env: Record<string, string | undefined> = process.env): V1Deps {
  return {
    config: () => apiV1Config(env),
    now: () => new Date(),
    replay,
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(key, { max, windowMs }),
    store: {
      listProjects: (userId, limit, after) => cyrusDb.cyrusProject.findMany({
        where: { userId, ...(after ? { OR: [{ createdAt: { lt: after.createdAt } }, { createdAt: after.createdAt, id: { lt: after.id } }] } : {}) },
        orderBy: [{ createdAt: "desc" }, { id: "desc" }], take: limit, select: PROJECT_SELECT,
      }),
      getProject: (id) => cyrusDb.cyrusProject.findUnique({ where: { id }, select: PROJECT_SELECT }),
      revisions: (ids) => cyrusDb.cyrusRevision.findMany({ where: { id: { in: ids } }, select: { id: true, projectId: true, seq: true, kind: true, status: true, message: true, modBuildId: true, manifest: true, spec: true, createdAt: true } }),
      getBuild: (id) => cyrusDb.modBuild.findUnique({
        where: { id },
        select: { id: true, userId: true, status: true, prompt: true, changeRequest: true, baseBuildId: true, rootBuildId: true, mcVersion: true, pluginName: true, version: true, result: true, error: true, errorCode: true, attempts: true, durationMs: true, jarName: true, jarSize: true, jarSha256: true, cyrus: true, createdAt: true, updatedAt: true, finishedAt: true },
      }),
    },
    catalog: () => fileCatalog(apiV1Config(env).catalogFile),
    planOf: (userId) => tierOf(userId),
    // same fail-closed licence rule as the sound library (lib/cyrus/sound/host.ts soundLibraryCleared)
    proprietaryCleared: () => env.CYRUS_SOUND_LIBRARY_CLEARED === "1",
    log: (m) => console.error(m),
  };
}

