    assert.equal((await runContentFilters(u, { strict: true, provenanceSource: "upload" })).status, "removed");
    assert.equal((await runContentFilters(u, { strict: true, provenanceSource: "user", derivedFrom: [sha("base")] })).status, "removed");
    assert.equal((await runContentFilters(u, { strict: true, provenanceSource: "user", derivedFrom: [] })).status, "published");
    const boom: ContentFilter = { id: "boom", check: () => { throw new Error("down"); } };
    assert.equal((await runContentFilters(u, { strict: true }, [...defaultFilters(), boom])).status, "held");
  });
