// Cyrus API v1 thin read-only slice (lib/cyrus/api/v1/http.ts) with fake deps: flag/config fail-closed, service tokens,
// scopes, rate limit, subject assertions (Ed25519, lifetime, replay, never email), owner checks, pagination, the catalog
// gates, error shape, and every 200 body validated against the Zod schemas the OpenAPI file is generated from.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash, generateKeyPairSync, randomBytes, type KeyObject } from "node:crypto";
import { handleV1, type BuildRow, type LiveOperationId, type ProjectRow, type RevisionRow, type V1Deps } from "../lib/cyrus/api/v1/http";
import { apiV1Config } from "../lib/cyrus/api/v1/config";
import { mintServiceToken, mintSubjectAssertion, ReplayCache, signWebhook, verifyWebhook, type SubjectClaims } from "../lib/cyrus/api/v1/signing";
import { BuildZ, CatalogEntryPublicZ, CatalogSearchZ, ErrorZ, HealthZ, ProjectDetailZ, ProjectListZ } from "../lib/cyrus/api/v1/schemas";
import { CatalogEntryV1Z, type CatalogEntry } from "../lib/cyrus/library/v2/entry";
import { createMemoryCatalogIndex } from "../lib/cyrus/library/v2/retrieval";

const NOW = new Date("2026-10-10T12:00:00Z");
const nowS = Math.floor(NOW.getTime() / 1000);
const sha = (s: string) => createHash("sha256").update(s).digest("hex");

const nx = generateKeyPairSync("ed25519");
const other = generateKeyPairSync("ed25519");
const spki = (k: KeyObject) => k.export({ format: "der", type: "spki" }).toString("base64");
const full = mintServiceToken("nxeon01");
const narrow = mintServiceToken("kodely01");
const slow = mintServiceToken("slow0001");
const ENV = {
  CYRUS_API_V1: "1",
  CYRUS_API_V1_KEYS: JSON.stringify([
    { id: "nxeon01", client: "nxeon", sha256: full.sha256, scopes: ["projects:read", "builds:read", "catalog:read", "bogus:scope"] },
    { id: "kodely01", client: "kodely", sha256: narrow.sha256, scopes: ["catalog:read"] },
    { id: "slow0001", client: "nxeon", sha256: slow.sha256, scopes: ["projects:read"], rpm: 2 },
  ]),
  CYRUS_API_V1_SUBJECT_KEYS: JSON.stringify([{ client: "nxeon", kid: "s1", publicKey: spki(nx.publicKey) }, { client: "kodely", kid: "k1", publicKey: spki(other.publicKey) }]),
};

const P = (id: string, userId: string, at: string, over: Partial<ProjectRow> = {}): ProjectRow => ({
  id, userId, game: "minecraft", namespace: "nx_abcd1234", title: `T ${id.slice(-2)}`, rootBuildId: null, headRevisionId: null, lastPassingRevisionId: null,
  revisionCount: 0, createdAt: new Date(at), updatedAt: new Date(at), ...over,
});
const SPEC = {
  schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace: "nx_abcd1234", summary: "A coin shop with a chest menu and /pay",
  routes: ["plugin"], requirements: [{ id: "REQ-1", text: "Players can /pay each other coins", priority: "must" }], nonGoals: [], constraints: [], assets: [],
  tests: [{ id: "T-1", kind: "compile", description: "The plugin compiles", covers: ["REQ-1"] }], install: { side: "server", restartRequired: true, clientSteps: [], notes: [] },
};
const pid = (n: number) => `cp${n.toString(16).padStart(20, "0")}`;
const PROJECTS: ProjectRow[] = [
  P(pid(1), "user_a", "2026-10-01T00:00:00Z", { headRevisionId: "rev2", lastPassingRevisionId: "rev1", revisionCount: 2 }),
  P(pid(2), "user_a", "2026-10-02T00:00:00Z"),
  P(pid(3), "user_a", "2026-10-02T00:00:00Z"),
  P(pid(4), "user_b", "2026-10-03T00:00:00Z", { headRevisionId: "revB" }),
  P(pid(5), "user_a", "2026-10-04T00:00:00Z"),
];
const REVS: RevisionRow[] = [
  { id: "rev1", projectId: pid(1), seq: 1, kind: "generated", status: "passed", message: null, modBuildId: "b1", manifest: [{ path: "a" }], spec: SPEC, createdAt: new Date("2026-10-01T01:00:00Z") },
  { id: "rev2", projectId: pid(1), seq: 2, kind: "edited", status: "pending", message: "tweak", modBuildId: null, manifest: [{ path: "a" }, { path: "b" }], spec: SPEC, createdAt: new Date("2026-10-01T02:00:00Z") },
  { id: "revB", projectId: pid(4), seq: 1, kind: "generated", status: "passed", message: null, modBuildId: null, manifest: [], spec: null, createdAt: new Date("2026-10-03T01:00:00Z") },
];
const B = (id: string, userId: string, over: Partial<BuildRow> = {}): BuildRow => ({
  id, userId, status: "succeeded", prompt: "a coin shop", changeRequest: null, baseBuildId: null, rootBuildId: id, mcVersion: "1.21.11", pluginName: "CoinShop", version: "1.0.0",
  result: { summary: "Adds /pay and a shop menu", files: ["x"] }, error: null, errorCode: null, attempts: 1, durationMs: 61000, jarName: "CoinShop.jar", jarSize: 12345,
  jarSha256: sha("jar"), cyrus: { model: "katara" }, createdAt: new Date("2026-10-05T00:00:00Z"), updatedAt: new Date("2026-10-05T00:01:00Z"), finishedAt: new Date("2026-10-05T00:01:00Z"), ...over,
});
const BUILDS = [B("b1", "user_a"), B("b2", "user_b"), B("b3", "user_a", { status: "failed", error: "compile error in Main.java", errorCode: "compile_failed", jarSha256: null, finishedAt: null })];

const E = (title: string, kind: CatalogEntry["kind"], tier: CatalogEntry["licence"]["tier"] = "cc0", over: Record<string, unknown> = {}): CatalogEntry => CatalogEntryV1Z.parse({
  schemaVersion: 1, id: sha(title + kind + tier), kind, title, shortDescription: `${title} for testing the API`, tags: ["test"], categories: { primary: "props/crates" }, style: null,
  quality: { score: 70, version: "cq-1", method: "t", measured: 1, checks: [] }, games: { minecraft: { fit: "good", reason: "fits" } }, tech: { format: kind === "sound" ? "ogg" : "png", bytes: 100 },
  licence: { tier, spdx: tier === "cc0" ? "CC0-1.0" : null, sourceUrl: null, attribution: null, status: "verified" }, provenance: { source: "kenney", pack: "p", path: "secret/inside/path.png", retrievedAt: null, via: null },
  legalClass: "platform-library", status: "published", enrichment: { by: "stage-a", confidence: 1, coverage: "full", at: "2026-10-10" }, ...over,
});
const ENTRIES = [
  E("Wooden crate", "texture"), E("Metal crate", "texture"), E("Crate break sound", "sound"), E("Crate open sound", "sound"),
  E("Crate creak sound", "sound", "proprietary-nxeon"), E("Held crate sound", "sound", "cc0", { status: "held" }),
];

type Opts = { env?: Record<string, string | undefined>; plan?: Record<string, unknown>; catalog?: boolean; cleared?: boolean; boom?: boolean };
function deps(o: Opts = {}): V1Deps & { replay: ReplayCache } {
  const env = o.env ?? ENV;
  const windows = new Map<string, number>();
  return {
    config: () => apiV1Config(env),
    now: () => NOW,
    replay: new ReplayCache(),
    rateLimit: (key, max) => { const n = (windows.get(key) ?? 0) + 1; windows.set(key, n); return { ok: n <= max, retryAfterSec: 42, remaining: Math.max(0, max - n) }; },
    store: {
      async listProjects(userId, limit, after) {
        if (o.boom) throw new Error("db down: postgresql://user:pw@host");
        return PROJECTS.filter((p) => p.userId === userId)
          .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime() || (a.id < b.id ? 1 : -1))
          .filter((p) => !after || p.createdAt < after.createdAt || (p.createdAt.getTime() === after.createdAt.getTime() && p.id < after.id)).slice(0, limit);
      },
      async getProject(id) { return PROJECTS.find((p) => p.id === id) ?? null; },
      async revisions(ids) { return REVS.filter((r) => ids.includes(r.id)); },
      async getBuild(id) { return BUILDS.find((b) => b.id === id) ?? null; },
    },
    catalog: async () => (o.catalog === false ? null : createMemoryCatalogIndex(ENTRIES)),
    planOf: async (u) => { const p = (o.plan ?? { user_a: "saka", user_b: "free" })[u]; if (p === "throw") throw new Error("no"); return p; },
    proprietaryCleared: () => !!o.cleared,
    requestId: () => "req_test",
  };
}

let jti = 0;
const claims = (over: Partial<SubjectClaims> & Record<string, unknown> = {}): SubjectClaims => ({ v: 1, iss: "nxeon", sub: "user_a", aud: "cyrus-api-v1", iat: nowS - 5, exp: nowS + 55, jti: `jti${String(++jti).padStart(8, "0")}`, ...over } as SubjectClaims);
const subj = (over: Partial<SubjectClaims> & Record<string, unknown> = {}, key = nx.privateKey) => mintSubjectAssertion(claims(over), key);

async function call(op: LiveOperationId, path: string, o: { token?: string | null; subject?: string | null; params?: Record<string, string>; method?: string; d?: V1Deps } = {}) {
  const headers: Record<string, string> = {};
  const tok = o.token === undefined ? full.token : o.token;
  if (tok) headers.authorization = `Bearer ${tok}`;
  const s = o.subject === undefined ? subj() : o.subject;
  if (s) headers["cyrus-subject"] = s;
  const res = await handleV1(op, new Request(`https://cyrus.test/api/cyrus/v1${path}`, { method: o.method ?? "GET", headers }), o.params ?? {}, o.d ?? deps());
  return { status: res.status, body: await res.json() as Record<string, any>, headers: res.headers };
}
const isErr = (body: unknown, code: string) => { ErrorZ.parse(body); assert.equal((body as any).error.code, code); assert.equal((body as any).error.requestId, "req_test"); };

describe("Cyrus API v1: fail closed", () => {
  it("flag off: every operation is a 404 (the route does not exist), even with a valid token", async () => {
    for (const env of [{ ...ENV, CYRUS_API_V1: undefined }, { ...ENV, CYRUS_API_V1: "0" }]) {
      const r = await call("getHealth", "/health", { d: deps({ env }) });
      assert.equal(r.status, 404); isErr(r.body, "not_found");
    }
  });
  it("malformed key config: 503 api_misconfigured, never open", async () => {
    for (const bad of ["{", "{}", JSON.stringify([{ id: "x", client: "nxeon", sha256: full.sha256 }]), JSON.stringify([{ id: "nxeon01", client: "nxeon", sha256: "zz" }])]) {
      const r = await call("getHealth", "/health", { d: deps({ env: { ...ENV, CYRUS_API_V1_KEYS: bad } }) });
      assert.equal(r.status, 503, bad); isErr(r.body, "api_misconfigured");
    }
    const r = await call("getHealth", "/health", { d: deps({ env: { ...ENV, CYRUS_API_V1_SUBJECT_KEYS: JSON.stringify([{ client: "nxeon", kid: "s1", publicKey: "AAAA" }]) } }) });
    assert.equal(r.status, 503);
  });
  it("flag on, no keys configured: 401 for everyone", async () => {
    const r = await call("getHealth", "/health", { d: deps({ env: { CYRUS_API_V1: "1" } }) });
    assert.equal(r.status, 401);
  });
  it("tokens: missing, malformed, unknown key, wrong secret are all the same 401", async () => {
    const wrong = `cyk_nxeon01_${randomBytes(32).toString("base64url")}`;
    for (const token of [null, "nope", "cyk_unknown1_" + "a".repeat(40), wrong]) {
      const r = await call("getHealth", "/health", { token });
      assert.equal(r.status, 401, String(token)); isErr(r.body, "unauthorized");
      assert.match(r.headers.get("www-authenticate") ?? "", /Bearer/);
    }
  });
  it("method mismatch is a 404", async () => {
    assert.equal((await call("getHealth", "/health", { method: "POST" })).status, 404);
  });
});

describe("Cyrus API v1: health, scopes, rate limit", () => {
  it("health: 200, client + known scopes only (unknown scope names are dropped)", async () => {
    const r = await call("getHealth", "/health", { subject: null });
    assert.equal(r.status, 200);
    HealthZ.parse(r.body);
    assert.equal(r.body.client, "nxeon");
    assert.deepEqual(r.body.scopes, ["projects:read", "builds:read", "catalog:read"]);
    assert.equal(r.headers.get("cache-control"), "no-store");
    assert.equal(r.headers.get("cyrus-request-id"), "req_test");
  });
  it("missing scope: 403 forbidden_scope", async () => {
    const r = await call("listProjects", "/projects", { token: narrow.token });
    assert.equal(r.status, 403); isErr(r.body, "forbidden_scope");
  });
  it("rate limit per key: 429 + Retry-After after rpm", async () => {
    const d = deps();
    assert.equal((await call("listProjects", "/projects", { token: slow.token, d })).status, 200);
    const second = await call("listProjects", "/projects", { token: slow.token, d });
    assert.equal(second.status, 200); assert.equal(second.headers.get("ratelimit-remaining"), "0");
    const r = await call("listProjects", "/projects", { token: slow.token, d });
    assert.equal(r.status, 429); isErr(r.body, "rate_limited"); assert.equal(r.headers.get("retry-after"), "42");
  });
});

describe("Cyrus API v1: subject assertions", () => {
  const bad = async (subject: string | null, code = "bad_subject", status = 401, d?: V1Deps) => {
    const r = await call("listProjects", "/projects", { subject, d });
    assert.equal(r.status, status); isErr(r.body, code);
    return r;
  };
  it("missing: 400 subject_required", async () => { await bad(null, "subject_required", 400); });
  it("signed by another client's key, or iss is not the token's client: 401", async () => {
    await bad(subj({}, other.privateKey));
    await bad(subj({ iss: "kodely" }, other.privateKey));
  });
  it("expired, issued in the future, too long-lived, wrong audience, bad version: 401", async () => {
    await bad(subj({ iat: nowS - 300, exp: nowS - 100 }));
    await bad(subj({ iat: nowS + 120, exp: nowS + 200 }));
    await bad(subj({ iat: nowS, exp: nowS + 3600 }));
    await bad(subj({ aud: "someone-else" }));
    await bad(subj({ v: 2 as 1 }));
  });
  it("never an email: an email claim or an @ in sub is refused", async () => {
    await bad(subj({ email: "a@b.c" }));
    await bad(subj({ sub: "a@b.c" }));
  });
  it("single use: a replayed assertion is refused", async () => {
    const d = deps();
    const s = subj();
    assert.equal((await call("listProjects", "/projects", { subject: s, d })).status, 200);
    await bad(s, "bad_subject", 401, d);
  });
  it("tampered payload: 401", async () => {
    const [, sig] = subj().split(".");
    await bad(`${Buffer.from(JSON.stringify(claims({ sub: "user_b" }))).toString("base64url")}.${sig}`);
    await bad("garbage");
  });
});

describe("Cyrus API v1: projects and builds", () => {
  it("lists only the subject's projects, newest first, with cursor pagination", async () => {
    const d = deps();
    const p1 = await call("listProjects", "/projects?limit=2", { d });
    assert.equal(p1.status, 200); ProjectListZ.parse(p1.body);
    assert.deepEqual(p1.body.data.map((p: any) => p.id), [pid(5), pid(3)]);
    assert.ok(p1.body.nextCursor);
    const p2 = await call("listProjects", `/projects?limit=2&cursor=${p1.body.nextCursor}`, { d });
    assert.deepEqual(p2.body.data.map((p: any) => p.id), [pid(2), pid(1)]);
    const p3 = await call("listProjects", `/projects?limit=2&cursor=${p2.body.nextCursor}`, { d });
    assert.deepEqual(p3.body.data, []); assert.equal(p3.body.nextCursor, null);
    assert.ok(!JSON.stringify(p1.body).includes("user_a"), "no user id in the payload");
  });
  it("bad limit / cursor: 400 with structured issues", async () => {
    const r = await call("listProjects", "/projects?limit=0");
    assert.equal(r.status, 400); isErr(r.body, "bad_request");
    assert.deepEqual(r.body.error.issues.map((i: any) => i.path), ["limit"]);
    const c = await call("listProjects", "/projects?cursor=bm9wZQ");
    assert.equal(c.status, 400); assert.equal(c.body.error.issues[0].path, "cursor");
  });
  it("get project: head + last passing + the head's ModSpec; someone else's or a bad id is a 404", async () => {
    const r = await call("getProject", `/projects/${pid(1)}`, { params: { projectId: pid(1) } });
    assert.equal(r.status, 200); ProjectDetailZ.parse(r.body);
    assert.equal(r.body.head.id, "rev2"); assert.equal(r.body.head.files, 2); assert.equal(r.body.lastPassing.id, "rev1");
    assert.equal(r.body.spec.namespace, "nx_abcd1234");
    for (const id of [pid(4), pid(99), "../etc", "cpXYZ"]) {
      const n = await call("getProject", `/projects/${id}`, { params: { projectId: id } });
      assert.equal(n.status, 404, id); isErr(n.body, "not_found");
    }
  });
  it("get build: public view only (no cost, no jar path), failed build carries the error; other user's is a 404", async () => {
    const r = await call("getBuild", "/builds/b1", { params: { buildId: "b1" } });
    assert.equal(r.status, 200); BuildZ.parse(r.body);
    assert.equal(r.body.terminal, true); assert.equal(r.body.summary, "Adds /pay and a shop menu"); assert.equal(r.body.artifact.sha256, sha("jar"));
    for (const k of ["costUsd", "jarPath", "userId", "result", "cyrus"]) assert.ok(!(k in r.body), k);
    const f = await call("getBuild", "/builds/b3", { params: { buildId: "b3" } });
    assert.deepEqual(f.body.error, { code: "compile_failed", message: "compile error in Main.java" }); assert.equal(f.body.artifact, null);
    assert.equal((await call("getBuild", "/builds/b2", { params: { buildId: "b2" } })).status, 404);
  });
  it("a store failure is a 500 with the request id and no internals", async () => {
    const logs: string[] = [];
    const d = { ...deps({ boom: true }), log: (m: string) => logs.push(m) };
    const r = await call("listProjects", "/projects", { d });
    assert.equal(r.status, 500); isErr(r.body, "internal");
    assert.ok(!JSON.stringify(r.body).includes("postgresql"));
    assert.equal(logs.length, 1);
  });
});

describe("Cyrus API v1: catalog", () => {
  it("search: plan-gated kinds and tiers, published only (saka = sounds, cc0 only until the library is cleared)", async () => {
    const r = await call("searchCatalog", "/catalog/search?q=crate&game=minecraft");
    assert.equal(r.status, 200); CatalogSearchZ.parse(r.body);
    const titles = r.body.data.map((h: any) => h.title).sort();
    assert.deepEqual(titles, ["Crate break sound", "Crate open sound"]);
    assert.ok(r.body.data.every((h: any) => h.ref === `cat:${h.id}` && h.fit === "good"));
    const cleared = await call("searchCatalog", "/catalog/search?q=crate", { d: deps({ cleared: true }) });
    assert.ok(cleared.body.data.some((h: any) => h.title === "Crate creak sound"));
  });
  it("search: kind the plan cannot use -> 403 asset_locked; free plan -> 403; unknown plan -> 403 plan_unknown", async () => {
    isErr((await call("searchCatalog", "/catalog/search?q=crate&kind=texture")).body, "asset_locked");
    isErr((await call("searchCatalog", "/catalog/search?q=crate", { subject: subj({ sub: "user_b" }) })).body, "asset_locked");
    const u = await call("searchCatalog", "/catalog/search?q=crate", { d: deps({ plan: { user_a: "throw" } }) });
    assert.equal(u.status, 403); isErr(u.body, "plan_unknown");
  });
  it("search: input issues are listed together; no catalog backend = 503", async () => {
    const r = await call("searchCatalog", "/catalog/search?q=x&kind=car&game=BAD");
    assert.equal(r.status, 400); assert.deepEqual(r.body.error.issues.map((i: any) => i.path), ["q", "kind", "game"]);
    const n = await call("searchCatalog", "/catalog/search?q=crate", { d: deps({ catalog: false }) });
    assert.equal(n.status, 503); isErr(n.body, "catalog_unavailable");
  });
  it("search pagination: limit + cursor walk the hits without repeats", async () => {
    const d = deps({ plan: { user_a: "all" } });
    const seen: string[] = [];
    let cursor: string | null = null, pages = 0;
    do {
      const r: any = await call("searchCatalog", `/catalog/search?q=crate&limit=2${cursor ? `&cursor=${cursor}` : ""}`, { d });
      assert.equal(r.status, 200);
      seen.push(...r.body.data.map((h: any) => h.id)); cursor = r.body.nextCursor; pages++;
    } while (cursor && pages < 10);
    assert.equal(new Set(seen).size, seen.length);
    assert.ok(seen.length >= 4 && pages >= 2);
  });
  it("get entry: public fields only (no provenance); gated or held entries are 404", async () => {
    const snd = ENTRIES[2];
    const r = await call("getCatalogEntry", `/catalog/entries/cat:${snd.id}`, { params: { entryId: `cat:${snd.id}` } });
    assert.equal(r.status, 200); CatalogEntryPublicZ.parse(r.body);
