type Opts = { env?: Record<string, string | undefined>; plan?: Record<string, unknown>; catalog?: boolean; cleared?: boolean; boom?: boolean };
function deps(o: Opts = {}): V1Deps & { replay: ReplayCache } {
  const env = o.env ?? ENV;
