  return {
    config: () => apiV1Config(env),
    now: () => NOW,
    replay: new ReplayCache(),
    rateLimit: (key, max) => { const n = (windows.get(key) ?? 0) + 1; windows.set(key, n); return { ok: n <= max, retryAfterSec: 42, remaining: Math.max(0, max - n) }; },
    store: {
      async listProjects(userId, limit, after) {
