describe("Cyrus API v1: webhook signatures (receiver side)", () => {
  const body = JSON.stringify({ id: "wh_1", type: "build.finished", data: {} });
  const ts = String(nowS);
  it("verifies, rejects tampering, stale timestamps and duplicates; accepts a rotation pair", () => {
    const replay = new ReplayCache();
    const sig = signWebhook("whsec", "wh_1", ts, body);
    assert.deepEqual(verifyWebhook({ secret: "whsec", id: "wh_1", timestamp: ts, body, signature: sig, nowMs: NOW.getTime(), replay }), { ok: true });
    assert.equal((verifyWebhook({ secret: "whsec", id: "wh_1", timestamp: ts, body, signature: sig, nowMs: NOW.getTime(), replay }) as any).code, "duplicate");
    assert.equal((verifyWebhook({ secret: "whsec", id: "wh_2", timestamp: ts, body: body + " ", signature: signWebhook("whsec", "wh_2", ts, body), nowMs: NOW.getTime(), replay }) as any).code, "bad_signature");
    assert.equal((verifyWebhook({ secret: "whsec", id: "wh_3", timestamp: String(nowS - 600), body, signature: signWebhook("whsec", "wh_3", String(nowS - 600), body), nowMs: NOW.getTime(), replay }) as any).code, "stale");
    const pair = `${signWebhook("old", "wh_4", ts, body)} ${signWebhook("whsec", "wh_4", ts, body)}`;
    assert.deepEqual(verifyWebhook({ secret: "whsec", id: "wh_4", timestamp: ts, body, signature: pair, nowMs: NOW.getTime(), replay }), { ok: true });
  });
});

