// The wire protocol of the HTTP host seam (direction A: a standalone Cyrus calls the platform's partner API for Cyrus).
// ONE table for both sides: lib/cyrus/host/http.ts (client, implements CyrusHost over fetch) and
// lib/cyrus/host/http-server.ts (reference server over ANY CyrusHost; the platform mounts it with its own host).
// Every call is `/<name>`: reads are GET with ?a=<JSON args>, writes are POST with a JSON body and an Idempotency-Key.
// Values travel through a JSON codec that keeps Buffers ({$b64}) and Dates ({$date}). Pure. HOST SEAM: no platform imports.

/** Where the platform mounts the reference server (nothing is mounted yet). */
export const HOST_API_PREFIX = "/api/partner/cyrus/host/v1";
export const HOST_API_VERSION = "1";

export type HostCallKind = "read" | "write";
/** Every remote call. `fs.*` act on a file session opened by servers.openFiles. */
export const HOST_CALLS = {
  "host.info": "read",
  "auth.user": "read",
  "access.isPreviewUser": "read",
  "settings.get": "read", "settings.getBool": "read", "settings.getInt": "read", "settings.getAll": "read",
  "settings.readStored": "read", "settings.readStoredPrefix": "read",
  "settings.set": "write", "settings.writeStored": "write", "settings.clearStored": "write",
  "worker.modLifecycleSweep": "write", "worker.modCompatWatchSweep": "write", "worker.syncModBuilds": "write",
  "users.get": "read", "users.emails": "read", "users.find": "read", "users.setBillingCustomerId": "write",
  "jobs.lastDone": "read",
  "servers.get": "read", "servers.listForUser": "read", "servers.planFamily": "read", "servers.paidCount": "read", "servers.lastHealthRun": "read",
  "servers.openFiles": "write",
  "fs.stat": "read", "fs.readFile": "read", "fs.list": "read",
  "fs.writeFile": "write", "fs.mkdirp": "write", "fs.rename": "write", "fs.remove": "write", "fs.chownLike": "write", "fs.copy": "write", "fs.close": "write",
  "records.onServer": "read", "records.serversWithSource": "read", "records.catalogId": "read", "records.ofMod": "read",
  "installs.install": "write", "installs.uninstall": "write",
  "audit.record": "write", "audit.append": "write",
} as const satisfies Record<string, HostCallKind>;
export type HostCallName = keyof typeof HOST_CALLS;
export const isHostCall = (n: string): n is HostCallName => Object.prototype.hasOwnProperty.call(HOST_CALLS, n);

/** What a client learns once (host.info) for the synchronous parts of CyrusHost. */
export type HostInfo = { version: string; statePath: string; roleAreas: Record<string, string[]> };
/** A server row on the wire: the platform's row plus the family it computed (servers.familyOf is synchronous). */
export type WireServerRow = { family?: string | null } & Record<string, unknown>;
export type HostReply = { ok: true; value: unknown } | { ok: false; error: { code: string; message: string } };

// ------------------------------------------------------------------------------------------------ codec
export function encodeWire(v: unknown): unknown {
  if (Buffer.isBuffer(v)) return { $b64: v.toString("base64") };
  if (v instanceof Date) return { $date: v.toISOString() };
  if (Array.isArray(v)) return v.map(encodeWire);
  if (v && typeof v === "object") {
    const o: Record<string, unknown> = {};
    for (const [k, x] of Object.entries(v)) if (x !== undefined && typeof x !== "function") o[k] = encodeWire(x);
    return o;
  }
  return v;
}
