// platform mounts it later (e.g. app/api/partner/cyrus/host/v1/[call]/route.ts -> handleHostRequest(req, nxeonHost));
// NOTHING mounts it today. Tests run it over a fake host to prove the interface works over HTTP. SERVER ONLY.
// Per request: signature (HMAC, timestamp window, nonce replay) -> known call + method -> idempotency replay for writes
// -> the host method. File sessions (servers.openFiles) live here, keyed by an unguessable id bound to the calling key.
// HOST SEAM: no platform imports.
import { randomBytes } from "node:crypto";
import type { CyrusHost, HostGuestFs } from "./types";
import { decodeWire, encodeWire, HOST_API_VERSION, HOST_CALLS, isHostCall, type HostCallName, type HostInfo, type HostReply } from "./http-protocol";
import { ReplayCache, verifyRequest } from "../api/v1/signing";

type Session = { fs: HostGuestFs; base: string; close?: () => void; keyId: string; expires: number };
export type HostServerOptions = {
  secretFor: (keyId: string) => string | null;
  /** role -> admin areas, for the client's synchronous access.canAccess */
  roleAreas: Record<string, string[]>;
  now?: () => number;
  replay?: ReplayCache;
  sessionTtlMs?: number;
  maxBodyBytes?: number;
};
export type HostServer = { handle(req: Request): Promise<Response>; sessions(): number; close(): void };

const reply = (status: number, body: HostReply) => Response.json(encodeWire(body), { status, headers: { "cache-control": "no-store", "cyrus-host-api": HOST_API_VERSION } });
const err = (status: number, code: string, message: string) => reply(status, { ok: false, error: { code, message } });
class CallError extends Error { constructor(public status: number, public code: string, message: string) { super(message); } }

export function createHostServer(host: CyrusHost, o: HostServerOptions): HostServer {
  const now = o.now ?? Date.now;
  const replay = o.replay ?? new ReplayCache();
  const ttl = o.sessionTtlMs ?? 10 * 60_000;
  const maxBody = o.maxBodyBytes ?? 64 * 1024 * 1024;
  const sessions = new Map<string, Session>();
  const idem = new Map<string, { at: number; status: number; text: string }>();

  const session = (keyId: string, id: unknown): Session => {
    const s = typeof id === "string" ? sessions.get(id) : undefined;
    if (!s || s.keyId !== keyId || s.expires < now()) throw new CallError(404, "no_session", "file session not found or expired");
    s.expires = now() + ttl;
    return s;
  };
  const sweep = () => { for (const [k, s] of sessions) if (s.expires < now()) { sessions.delete(k); try { s.close?.(); } catch { /* best effort */ } } };

  type A = Record<string, unknown>;
  const s = (a: A, k: string) => a[k] as string;
  const calls: Record<HostCallName, (a: A, keyId: string) => Promise<unknown>> = {
    "host.info": async () => ({ version: HOST_API_VERSION, statePath: host.installs.statePath, roleAreas: o.roleAreas } satisfies HostInfo),
    "auth.user": async (a) => {
      // the client's own session names a subject; the platform returns that account's basics (never a session)
      const u = await host.users.get(s(a, "subject"));
      return u ? { id: u.id, email: u.email, role: typeof a.role === "string" ? a.role : "USER" } : null;
    },
    "access.isPreviewUser": async (a) => host.access.isPreviewUser(a.user as { email?: string | null }, a.feature as "modbuilder"),
    "settings.get": async (a) => host.settings.get(s(a, "key"), a.fallback as string | undefined),
    "settings.getBool": async (a) => host.settings.getBool(s(a, "key"), a.fallback as boolean | undefined),
    "settings.getInt": async (a) => host.settings.getInt(s(a, "key"), a.fallback as number | undefined),
    "settings.getAll": async () => host.settings.getAll(),
    "settings.readStored": async (a) => host.settings.readStored(a.keys as string[]),
    "settings.readStoredPrefix": async (a) => host.settings.readStoredPrefix(s(a, "prefix")),
    "settings.set": async (a) => host.settings.set(s(a, "key"), s(a, "value")),
    "settings.writeStored": async (a) => host.settings.writeStored(s(a, "key"), s(a, "value")),
    "settings.clearStored": async (a) => host.settings.clearStored(s(a, "key")),
    "worker.modLifecycleSweep": async () => host.worker.modLifecycleSweep(),
    "worker.modCompatWatchSweep": async () => host.worker.modCompatWatchSweep(),
    "worker.syncModBuilds": async () => host.worker.syncModBuilds(),
    "users.get": async (a) => host.users.get(s(a, "id")),
    "users.emails": async (a) => host.users.emails(a.ids as string[]),
    "users.find": async (a) => host.users.find(s(a, "query")),
    "users.setBillingCustomerId": async (a) => host.users.setBillingCustomerId(s(a, "userId"), s(a, "customerId")),
    "jobs.lastDone": async (a) => host.jobs.lastDone(s(a, "serverId"), a.types as string[]),
    "servers.get": async (a) => { const r = await host.servers.get(s(a, "serverId")); return r ? { ...r, family: host.servers.familyOf(r) } : null; },
    "servers.listForUser": async (a) => (await host.servers.listForUser(s(a, "userId"))).map((r) => ({ ...r, family: host.servers.familyOf(r) })),
    "servers.planFamily": async (a) => host.servers.planFamily(s(a, "serverId")),
    "servers.paidCount": async (a) => host.servers.paidCount(s(a, "userId")),
    "servers.lastHealthRun": async (a) => host.servers.lastHealthRun(s(a, "serverId")),
    "servers.openFiles": async (a, keyId) => {
      sweep();
      const f = await host.servers.openFiles(s(a, "userId"), s(a, "serverId"));
      if (!f) return null;
      const id = randomBytes(18).toString("base64url");
      sessions.set(id, { ...f, keyId, expires: now() + ttl });
      return { session: id, base: f.base, kind: f.fs.kind };
    },
    "fs.stat": async (a, k) => session(k, a.session).fs.stat(s(a, "p")),
    "fs.readFile": async (a, k) => session(k, a.session).fs.readFile(s(a, "p"), a.maxBytes as number | undefined),
    "fs.list": async (a, k) => session(k, a.session).fs.list(s(a, "dir")),
    "fs.writeFile": async (a, k) => session(k, a.session).fs.writeFile(s(a, "p"), a.data as Buffer),
    "fs.mkdirp": async (a, k) => session(k, a.session).fs.mkdirp(s(a, "p")),
    "fs.rename": async (a, k) => session(k, a.session).fs.rename(s(a, "from"), s(a, "to")),
    "fs.remove": async (a, k) => session(k, a.session).fs.remove(s(a, "p")),
    "fs.chownLike": async (a, k) => session(k, a.session).fs.chownLike(s(a, "ref"), a.paths as string[]),
    "fs.copy": async (a, k) => session(k, a.session).fs.copy(s(a, "from"), s(a, "to")),
    "fs.close": async (a, k) => { const x = session(k, a.session); sessions.delete(a.session as string); x.close?.(); return null; },
    "records.onServer": async (a) => host.records.onServer(s(a, "serverId"), s(a, "source")),
    "records.serversWithSource": async (a) => host.records.serversWithSource(a.serverIds as string[], s(a, "source")),
    "records.catalogId": async (a) => host.records.catalogId(s(a, "source"), s(a, "sourceId")),
    "records.ofMod": async (a) => host.records.ofMod(s(a, "modId"), a.serverIds as string[]),
    "installs.install": async (a, k) => { const x = session(k, a.session); return host.installs.install({ ...(a.args as Omit<Parameters<CyrusHost["installs"]["install"]>[0], "fs">), fs: x.fs }); },
    "installs.uninstall": async (a, k) => { const x = session(k, a.session); return host.installs.uninstall({ ...(a.args as Omit<Parameters<CyrusHost["installs"]["uninstall"]>[0], "fs">), fs: x.fs }); },
    "audit.record": async (a) => host.audit.record(a.userId as string | null, s(a, "action"), a.detail as string | undefined),
    "audit.append": async (a) => host.audit.append(a.row as Parameters<CyrusHost["audit"]["append"]>[0]),
  };

  async function handle(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const name = decodeURIComponent(url.pathname.split("/").pop() ?? "");
    const body = req.method === "POST" ? Buffer.from(await req.arrayBuffer()) : Buffer.alloc(0);
    if (body.length > maxBody) return err(413, "too_large", "request body too large");
    const check = verifyRequest({ header: (h) => req.headers.get(h), method: req.method, pathWithQuery: url.pathname + url.search, body, secretFor: o.secretFor, nowMs: now(), replay });
    if (!check.ok) return err(401, check.code, "request signature refused");
    if (!isHostCall(name)) return err(404, "unknown_call", `no host call ${name}`);
    const kind = HOST_CALLS[name];
    if ((kind === "read") !== (req.method === "GET")) return err(405, "wrong_method", `${name} is a ${kind}`);
    let args: Record<string, unknown>;
    try {
      const raw = kind === "read" ? url.searchParams.get("a") ?? "{}" : body.toString("utf8") || "{}";
      args = decodeWire(JSON.parse(raw)) as Record<string, unknown>;
      if (!args || typeof args !== "object" || Array.isArray(args)) throw new Error();
    } catch { return err(400, "bad_args", "arguments are not a JSON object"); }
    let idemKey: string | null = null;
    if (kind === "write") {
      const k = req.headers.get("idempotency-key");
      if (!k || !/^[A-Za-z0-9_-]{8,128}$/.test(k)) return err(400, "idempotency_key_required", "writes need an Idempotency-Key");
      idemKey = `${check.keyId}:${k}`;
      for (const [x, v] of idem) if (v.at < now() - 24 * 3600_000) idem.delete(x); else break;
      const hit = idem.get(idemKey);
      if (hit) return new Response(hit.text, { status: hit.status, headers: { "content-type": "application/json", "cyrus-host-api": HOST_API_VERSION, "idempotent-replay": "true" } });
    }
    let res: Response;
    try {
      res = reply(200, { ok: true, value: (await calls[name](args, check.keyId)) ?? null });
    } catch (e) {
      res = e instanceof CallError ? err(e.status, e.code, e.message) : err(500, "host_error", (e as Error).message?.slice(0, 300) || "host call failed");
    }
    if (idemKey && res.status < 500) {
      const text = await res.clone().text();
      idem.set(idemKey, { at: now(), status: res.status, text });
    }
    return res;
  }

  return {
    handle,
    sessions: () => sessions.size,
    close: () => { for (const x of sessions.values()) try { x.close?.(); } catch { /* best effort */ } sessions.clear(); },
  };
}

