    "installs.uninstall": async (a, k) => { const x = session(k, a.session); return host.installs.uninstall({ ...(a.args as Omit<Parameters<CyrusHost["installs"]["uninstall"]>[0], "fs">), fs: x.fs }); },
    "audit.record": async (a) => host.audit.record(a.userId as string | null, s(a, "action"), a.detail as string | undefined),
    "audit.append": async (a) => host.audit.append(a.row as Parameters<CyrusHost["audit"]["append"]>[0]),
  };

  async function handle(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const name = decodeURIComponent(url.pathname.split("/").pop() ?? "");
    const body = req.method === "POST" ? Buffer.from(await req.arrayBuffer()) : Buffer.alloc(0);
    if (body.length > maxBody) return err(413, "too_large", "request body too large");
    const check = verifyRequest({ header: (h) => req.headers.get(h), method: req.method, pathWithQuery: url.pathname + url.search, body, secretFor: o.secretFor, nowMs: now(), replay });
    if (!check.ok) return err(401, check.code, "request signature refused");
    if (!isHostCall(name)) return err(404, "unknown_call", `no host call ${name}`);
    const kind = HOST_CALLS[name];
    if ((kind === "read") !== (req.method === "GET")) return err(405, "wrong_method", `${name} is a ${kind}`);
    let args: Record<string, unknown>;
    try {
      const raw = kind === "read" ? url.searchParams.get("a") ?? "{}" : body.toString("utf8") || "{}";
      args = decodeWire(JSON.parse(raw)) as Record<string, unknown>;
      if (!args || typeof args !== "object" || Array.isArray(args)) throw new Error();
    } catch { return err(400, "bad_args", "arguments are not a JSON object"); }
    let idemKey: string | null = null;
    if (kind === "write") {
      const k = req.headers.get("idempotency-key");
      if (!k || !/^[A-Za-z0-9_-]{8,128}$/.test(k)) return err(400, "idempotency_key_required", "writes need an Idempotency-Key");
      idemKey = `${check.keyId}:${k}`;
      for (const [x, v] of idem) if (v.at < now() - 24 * 3600_000) idem.delete(x); else break;
      const hit = idem.get(idemKey);
      if (hit) return new Response(hit.text, { status: hit.status, headers: { "content-type": "application/json", "cyrus-host-api": HOST_API_VERSION, "idempotent-replay": "true" } });
    }
    let res: Response;
    try {
      res = reply(200, { ok: true, value: (await calls[name](args, check.keyId)) ?? null });
    } catch (e) {
      res = e instanceof CallError ? err(e.status, e.code, e.message) : err(500, "host_error", (e as Error).message?.slice(0, 300) || "host call failed");
    }
    if (idemKey && res.status < 500) {
      const text = await res.clone().text();
      idem.set(idemKey, { at: now(), status: res.status, text });
    }
    return res;
  }

  return {
    handle,
    sessions: () => sessions.size,
    close: () => { for (const x of sessions.values()) try { x.close?.(); } catch { /* best effort */ } sessions.clear(); },
  };
}

